/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A45 staging · exact frozen manifest heroic–history (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});
P('heroic','heroic 由 hero 加 -ic 构成，表示像英雄般勇敢，尤指面对危险时表现出的勇气。',C('heroic.s1','灾害救援','The firefighter made a heroic effort to reach the stranded family before floodwater closed the last safe road.','消防员奋力在洪水封住最后一条安全道路前赶到被困家庭身边。','The firefighter made a heroic effort / to reach the stranded family / before floodwater closed / the last safe road.','heroic 修饰 effort，强调面对危险的勇敢行动；before 从句说明时间紧迫。','救援者冒险帮助被困者，符合英勇义。'),M('The report called the firefighter heroic for avoiding all danger and refusing to help the stranded family.','The report called the firefighter cautious for avoiding danger and refusing the rescue.','拒绝救援并避免承担风险，不能作为英勇行动的依据。'),[Q('heroic',1,1,'A heroic act shows?','great bravery, especially in danger','a routine daily habit','a high price','heroic 指英勇的。'),Q('heroic',2,1,'Which action is heroic?','entering a dangerous area to rescue someone','leaving a stranded person without help','quietly reading a history book','冒险救人体现英勇。'),Q('heroic',3,1,'The suffix -ic in heroic forms an?','adjective describing a hero-like quality','adverb meaning silently','plural noun for heroes','heroic 是形容词。'),Q('heroic',4,1,'A heroic effort is most likely?','brave and demanding','careless and ordinary','deliberately dishonest','heroic effort 指勇敢的努力。')]);
P('heroin','heroin 是吗啡相关的强效非法阿片类药物名称，词源经德语 Heroin；它具有高度成瘾和严重健康风险。',C('heroin.s1','公共卫生','The public health notice explained that heroin is a powerful illegal opioid and directed readers to confidential addiction-treatment services.','公共卫生公告说明海洛因是一种强效非法阿片类药物，并为读者提供保密的成瘾治疗服务信息。','The public health notice explained that heroin is a powerful illegal opioid / and directed readers / to confidential addiction-treatment services.','heroin 在此指非法阿片类药物；并列结构同时提供风险说明和求助信息。','公告将其描述为强效非法毒品，符合 s1。'),M('The brochure called heroin a harmless vitamin supplement that prevents addiction and has no health risks.','The brochure called heroin a powerful illegal opioid with serious health risks and addiction potential.','把危险的成瘾性药物称作无害维生素与事实相反。'),[Q('heroin',1,1,'Heroin is?','a powerful illegal opioid drug related to morphine','a harmless food seasoning','a kind of fish','heroin 指强效非法阿片类药物。'),Q('heroin',2,2,'A public health notice about heroin should emphasize?','its serious risks and access to treatment','that it is safe for casual use','how to make it at home','公共卫生信息应聚焦风险与治疗资源。'),Q('heroin',3,1,'Heroin belongs to which broad drug class?','opioids','antibiotics','vitamins','海洛因属于阿片类药物。'),Q('heroin',4,2,'A person concerned about heroin dependence should be directed toward?','qualified health and addiction-support services','an unverified online seller','instructions for increasing a dose','应联系专业医疗和成瘾支持服务。')]);
P('heroine','heroine 由 hero 加阴性人物后缀 -ine 构成，可指女英雄，也可指作品中的女性主人公。',C('heroine.s2','文学阅读','The novel’s heroine narrates the story herself, describing how she uncovers the family secret and changes her town.','小说的女主角亲自讲述故事，描写她如何揭开家族秘密并改变自己的小镇。','The novel’s heroine narrates the story herself / describing how she uncovers / the family secret / and changes her town.','heroine 在 novel’s 后指女性主人公；herself 强调叙述者就是她本人。','她是小说的女性主要角色，符合 s2。'),M('The novel’s heroine was described as its main female character, although the story had no female character at all.','The novel’s hero was described as its main male character.','没有女性角色的故事不能把某人称为女性主人公。'),[Q('heroine',1,1,'A heroine is?','a woman known for brave acts or the main female character','a male villain in every story','a kind of old coin','heroine 可指女英雄或女主角。'),Q('heroine',2,2,'The heroine of a novel is usually?','its main female character','the person who prints the book','a minor setting','heroine 可指小说女主角。'),Q('heroine',3,1,'Which person might be called a heroine?','a woman who courageously saves others','a person who abandons a rescue','a fish sold at market','勇敢救人的女性可称 heroine。'),Q('heroine',4,2,'The word heroine is related to?','hero','herring','history','heroine 由 hero 派生。')]);
P('heroism','heroism 由 hero 加 -ism 构成，指尤其在危险情境中表现出的令人敬佩的勇敢行为。',C('heroism.s1','社区救助','Neighbors praised the teenagers’ heroism after they guided an elderly resident out of the smoke-filled building.','青少年引导一位年长居民离开充满烟雾的楼房后，邻居们称赞了他们的英勇行为。','Neighbors praised the teenagers’ heroism / after they guided an elderly resident / out of the smoke-filled building.','heroism 是名词，指英勇行为；after 从句说明受到称赞的原因。','青少年在危险中帮助居民脱险，体现 heroism。'),M('The article called it heroism when the witnesses watched the emergency and deliberately refused to help.','The article called it indifference when the witnesses watched the emergency and refused to help.','袖手旁观而拒绝帮助体现冷漠，不是英勇。'),[Q('heroism',1,1,'Heroism is?','impressive bravery, especially in danger','a small hiccup','a style of writing','heroism 指英勇行为。'),Q('heroism',2,1,'A rescue performed at personal risk may show?','heroism','hesitation only','heterogeneity','冒险救援体现英勇。'),Q('heroism',3,1,'Which phrase is natural?','an act of heroism','a herring of heroism','a hierarchy of heroism','act of heroism 是常见搭配。'),Q('heroism',4,1,'The closest word to heroism is?','bravery','cowardice','routine','bravery 与 heroism 意义接近。')]);
P('herring','herring 源自古英语 hǣring，指在北大西洋成群游动、常供食用的鲱鱼。',C('herring.s1','海鲜市场','The fishmonger sold smoked herring beside the fresh catch, and the label listed the fish’s source and storage date.','鱼贩在新鲜渔获旁出售烟熏鲱鱼，标签列出了鱼的来源和储存日期。','The fishmonger sold smoked herring / beside the fresh catch / and the label listed / the fish’s source and storage date.','smoked herring 指烟熏鲱鱼；fishmonger 与食用鱼类的销售语境相符。','烟熏后出售的北大西洋鱼类指 herring。'),M('The menu listed smoked herring as a fruit grown on a tree.','The menu listed smoked herring as a fish prepared by smoking.','herring 是鱼类，不是树上生长的水果。'),[Q('herring',1,1,'A herring is?','a fish that often swims in large schools','a small mammal that hibernates','a six-sided polygon','herring 指鲱鱼。'),Q('herring',2,1,'Smoked herring is?','fish preserved and flavored by smoking','a kind of seaweed','a vegetarian grain','烟熏鲱鱼是经烟熏处理的鱼。'),Q('herring',3,1,'Herring are commonly associated with?','the North Atlantic','the Sahara Desert','mountain forests only','鲱鱼常见于北大西洋。'),Q('herring',4,1,'Which phrase is natural?','a school of herring','a hierarchy of herring','a haircut of herring','鲱鱼常成群游动，可说 a school of herring。')]);
P('hers','hers 是 her 的名词性物主代词，表示属于她的东西，并可代替前文提到的名词。',C('hers.s2','物品辨认','Two umbrellas were left by the door: mine was black, and hers was the red one with a wooden handle.','门边留下两把伞：我的那把是黑色的，她的那把是带木柄的红伞。','Two umbrellas were left by the door / mine was black / and hers was the red one / with a wooden handle.','hers 独立作名词性物主代词，代替 hers umbrella，不再接名词。','hers 指前文提到、属于她的那把伞，符合 s2。'),M('This red umbrella is hers book, so she took it home.','This red umbrella is hers, so she took it home.','hers 后不能直接接名词；限定词应使用 her book。'),[Q('hers',1,1,'In “That coat is hers,” hers means?','the coat belongs to her','she owns the speaker','the coat belongs to them','hers 表示“她的”，此处代替名词。'),Q('hers',2,2,'Which sentence uses hers correctly?','My seat is near hers.','My seat is near hers chair.','My seat is near she.','hers 可独立代替名词短语。'),Q('hers',3,1,'Choose the possessive pronoun for something belonging to her.','hers','her','herself','名词性物主代词是 hers。'),Q('hers',4,2,'In “The blue bag is hers,” hers avoids repeating?','the blue bag','the person’s name only','the word blue','hers 代替前文的名词短语。')]);
P('herself','herself 可作反身代词指女性主语本人，也可用于强调“她亲自”，或表示恢复到平常状态。',C('herself.s3','康复叙述','After a quiet week at home, Maya said she was beginning to feel herself again and returned to her usual walks.','在家安静休息一周后，玛雅说自己开始恢复平常状态，并重新进行日常散步。','After a quiet week at home / Maya said she was beginning to feel herself again / and returned / to her usual walks.','feel herself again 表示恢复平日的身心状态；again 强调状态回归。','她恢复平时的状态并重拾日常活动，符合 s3。'),M('After the fever passed, Maya said she felt herself again but meant she had become entirely unlike her usual self.','After the fever passed, Maya said she still did not feel herself and had not returned to normal.','feel herself again 表示恢复常态，不是变得完全不像自己。'),[Q('herself',1,1,'In “She hurt herself,” herself refers to?','the same female person as the subject','a different woman','a place in a hierarchy','反身代词指回主语。'),Q('herself',2,2,'“She herself opened the letter” emphasizes that?','she personally opened it','someone else opened it','the letter was hidden','herself 可用于强调她本人亲自做。'),Q('herself',3,3,'If she feels herself again, she?','has returned to her usual state','has hidden her identity','is introducing another person','feel herself again 表示恢复如常。'),Q('herself',4,1,'Which sentence uses the reflexive form?','She reminded herself to call.','The reminder was hers.','She saw him at the station.','reminded herself 中反身代词回指主语。')]);
P('hesitant','hesitant 源自拉丁语 haesitare“犹豫、停顿”，形容因不确定或缺乏信心而行动、说话迟缓的。',C('hesitant.s1','决策讨论','The hesitant buyer asked for one more day to compare the repair estimates before choosing a contractor.','犹豫的买家要求再多一天比较维修报价，然后才选择承包商。','The hesitant buyer asked for one more day / to compare the repair estimates / before choosing a contractor.','hesitant 修饰 buyer，说明其尚未决定；before 引出决定前的比较。','买家因拿不定主意而推迟选择，符合 s1。'),M('The hesitant buyer chose a contractor immediately without pausing, comparing options, or expressing any doubt.','The decisive buyer chose a contractor immediately without pausing or expressing doubt.','立即果断选择且毫无疑虑，不体现 hesitant。'),[Q('hesitant',1,1,'A hesitant person is?','slow to act or speak because of doubt','certain and eager to act','already finished the task','hesitant 表示犹豫的。'),Q('hesitant',2,1,'A hesitant answer may include?','pauses and uncertainty','instant certainty','a loud burst of laughter','犹豫回答常带停顿和不确定。'),Q('hesitant',3,1,'Which person seems hesitant?','someone delaying a choice while weighing options','someone who decides instantly with confidence','someone giving a practiced speech','权衡后迟迟不决定体现犹豫。'),Q('hesitant',4,1,'The closest opposite of hesitant is?','decisive','uncertain','reluctant','decisive 表示果断。')]);
P('hesitate','hesitate 源自拉丁语 haesitare，指行动前停顿，也可表示不愿做某事或说话支吾。',C('hesitate.s2','安全决策','She hesitated to sign the release form because she had not yet received an explanation of its terms.','她不愿签署免责表，因为还没有人向她解释其中条款。','She hesitated to sign the release form / because she had not yet received / an explanation of its terms.','hesitate to do 可表达对某行动有顾虑、不愿贸然去做；because 引出原因。','她因不了解条款而不愿签字，符合 s2。'),M('He hesitated to accept the offer because he was eager, certain, and had no concern about it.','He accepted the offer immediately because he was eager and had no concerns.','完全没有顾虑且急于接受，与 hesitate 表示不愿或犹豫相反。'),[Q('hesitate',1,1,'To hesitate before answering is to?','pause because one is unsure','reply instantly with certainty','forget the question completely','hesitate 可指犹豫停顿。'),Q('hesitate',2,2,'“I hesitate to recommend it” suggests?','I am reluctant or have reservations about recommending it','I strongly recommend it without doubt','I have already purchased it','hesitate to 可表示不愿或有所顾虑。'),Q('hesitate',3,3,'A speaker may hesitate by?','pausing and speaking with uncertainty','reading smoothly without a pause','singing loudly','说话停顿、支吾是 hesitate 的一种用法。'),Q('hesitate',4,1,'Which sentence uses hesitate naturally?','Do not hesitate to ask if you need help.','Please hesitate the window closed.','The road hesitated the bus.','do not hesitate to 表示不必犹豫去做。')]);
P('hesitation','hesitation 源自 hesitate，加名词后缀 -ation，可指因疑虑而停顿，也可指说话中的支吾停顿。',C('hesitation.s2','公开发言','There was a brief hesitation in the witness’s answer, followed by a clear correction of the date.','证人的回答中短暂地支吾了一下，随后清楚地更正了日期。','There was a brief hesitation in the witness’s answer / followed by a clear correction / of the date.','hesitation 指说话时因紧张或不确定而有的停顿；followed by 表示随后出现的更正。','短暂支吾后再纠正日期，符合 s2。'),M('Her hesitation showed in her speech as she delivered every sentence smoothly with no pauses or uncertainty.','Her confidence showed in her speech as she delivered every sentence smoothly with no pauses or uncertainty.','流畅且毫无停顿的表达不能作为 hesitation 的表现。'),[Q('hesitation',1,1,'Hesitation before acting is?','a pause caused by doubt or unwillingness','a sudden immediate decision','a permanent rule','hesitation 指因犹豫而停顿。'),Q('hesitation',2,2,'A hesitation in speech may sound like?','brief pauses or uncertain sounds','a perfectly continuous sentence','a musical chord','说话支吾会出现短暂停顿。'),Q('hesitation',3,1,'Which behavior shows hesitation?','pausing before signing because of uncertainty','signing immediately with no doubt','finishing a task confidently','因不确定而停顿体现 hesitation。'),Q('hesitation',4,2,'The noun hesitation is related to which verb?','hesitate','hide','hiss','hesitation 与 hesitate 同源。')]);
P('heterodox','heterodox 源自希腊语 heteros“不同”与 doxa“观点”，形容与官方或普遍接受的信念、做法相悖的。',C('heterodox.s1','学术争论','The professor defended a heterodox interpretation of the poem, arguing that its familiar ending had been misread for generations.','教授为一种非正统的诗歌解读辩护，认为人们几代以来都误读了熟悉的结尾。','The professor defended a heterodox interpretation / of the poem / arguing that its familiar ending / had been misread for generations.','heterodox 修饰 interpretation，表示偏离主流观点；arguing 补充其理由。','该解读挑战长期普遍接受的看法，符合 s1。'),M('The article called the theory heterodox while stating that it exactly matched every official and widely accepted view.','The article called the theory orthodox because it matched the official and widely accepted view.','完全符合官方和普遍观点的是正统，而非 heterodox。'),[Q('heterodox',1,1,'A heterodox opinion is?','contrary to what is generally or officially accepted','identical to every accepted doctrine','a kind of fish','heterodox 表示非正统的。'),Q('heterodox',2,1,'A heterodox theory may?','challenge a widely accepted explanation','repeat the standard view without change','describe a six-sided shape','挑战主流解释符合 heterodox。'),Q('heterodox',3,1,'The prefix hetero- means?','different or other','same','half','hetero- 表示不同。'),Q('heterodox',4,1,'The closest contrast to heterodox is?','orthodox','unusual','unpopular','orthodox 表示正统，与 heterodox 相反。')]);
P('heterogeneous','heterogeneous 源自希腊语 heteros“不同”与 genos“种类”，表示由彼此不同的部分或成员组成。',C('heterogeneous.s2','研究样本','The survey included a heterogeneous group of residents, with participants ranging from teenagers to retirees and from renters to homeowners.','这项调查纳入了成分多样的居民群体，参与者既有青少年也有退休者，既有租客也有业主。','The survey included a heterogeneous group of residents / with participants ranging from teenagers to retirees / and from renters to homeowners.','heterogeneous 修饰 group，表示群体成员类型多样；with 短语列举差异。','样本成员在年龄和住房情况上种类不同，符合 s2。'),M('The sample was called heterogeneous even though every participant had exactly the same age, job, and background.','The sample was called homogeneous because every participant had the same age, job, and background.','成员完全相同的群体是 homogeneous，不是 heterogeneous。'),[Q('heterogeneous',1,1,'A heterogeneous collection contains?','parts or members of different kinds','only identical objects','six equal sides','heterogeneous 表示成分不同。'),Q('heterogeneous',2,2,'A heterogeneous study group might include?','people with varied ages and backgrounds','twenty identical copies of one person','only one kind of data point','多样化成员符合 heterogeneous。'),Q('heterogeneous',3,1,'A heterogeneous mixture is unlike a uniform one because?','its components differ from one another','all its parts are necessarily identical','it has no parts at all','不同成分构成异质混合物。'),Q('heterogeneous',4,2,'The closest opposite of heterogeneous is?','homogeneous','diverse','mixed','homogeneous 表示同质的。')]);
P('heuristic','heuristic 源自希腊语 heuriskein“发现”，形容通过实践尝试帮助学习或解决问题、但不保证最佳结果的方法。',C('heuristic.s2','问题解决','The team used a simple heuristic—checking the most recently changed files first—to narrow the search for the bug.','团队采用了一条简单的启发式策略——先检查最近修改的文件——以缩小查找故障的范围。','The team used a simple heuristic / checking the most recently changed files first / to narrow the search / for the bug.','heuristic 指实用但不保证最优的规则；破折号后举例说明具体策略。','先查近期修改项是便于发现问题的经验规则，符合 s2。'),M('The team called its heuristic a guaranteed proof that always found the best solution for every possible case.','The team called its heuristic a practical rule that often helped but did not guarantee the best solution.','heuristic 是实用启发方法，不是对所有情况都保证最优的证明。'),[Q('heuristic',1,1,'A heuristic method is?','a practical way to guide discovery or problem-solving','a proof that guarantees the best answer','a six-sided polygon','heuristic 指启发式方法。'),Q('heuristic',2,2,'A heuristic is useful because it?','often works in practice without guaranteeing the optimum','always proves the only possible answer','eliminates all need for judgment','启发式规则常有用但不保证最优。'),Q('heuristic',3,1,'Checking the newest files first is a heuristic if it?','serves as a practical search rule','is a theorem proving every bug’s cause','is a type of herring','经验性搜索策略属于 heuristic。'),Q('heuristic',4,2,'The word heuristic is linked to the idea of?','finding or discovering','hiding something','making a loud hiss','其词源与“发现”相关。')]);
P('hew','hew 源自古英语 heawan，可指用工具砍、劈木石，也可在 hew to 中表示严格遵守或坚持。',C('hew.s2','制度执行','The review board agreed to hew to the published criteria so that every applicant would be judged by the same standards.','评审委员会同意严格遵守已公布的标准，以便按同一尺度评判每位申请者。','The review board agreed to hew to the published criteria / so that every applicant / would be judged / by the same standards.','hew to + 原则或标准表示遵循、坚持；so that 引出一致评审的目的。','委员会坚持按既定标准办事，符合 s2。'),M('The board promised to hew to the published rules but ignored every requirement as soon as review began.','The board promised to follow the published rules and apply each requirement during review.','完全忽略规则与 hew to（遵循）相矛盾。'),[Q('hew',1,1,'To hew a log is to?','chop or shape it with a tool','hide it under a blanket','measure its history','hew 可指砍削木头。'),Q('hew',2,2,'To hew to a rule is to?','follow it strictly','break it deliberately','write it in hieroglyphs','hew to 表示严格遵守。'),Q('hew',3,1,'Which sentence uses hew in its literal sense?','Workers hewed the stone into blocks.','The committee hewed to its policy.','The rumor hewed the town.','hew stone 表示砍凿石块。'),Q('hew',4,2,'Which phrase is idiomatic?','hew to a principle','hew a greeting','hew a highway into a herring','hew to 表示坚持原则。')]);
P('hexagon','hexagon 源自希腊语 hex“六”与 gonia“角”，指有六条边、六个角的多边形。',C('hexagon.s1','几何课堂','The students drew a regular hexagon and measured each side to confirm that all six edges were equal.','学生们画了一个正六边形，并测量每条边以确认六条边长度相等。','The students drew a regular hexagon / and measured each side / to confirm / that all six edges were equal.','hexagon 指六边形；regular 表示边角规则，后句验证边长相等。','图形有六条边和六个角，符合 s1。'),M('The diagram labeled a shape with five sides as a hexagon.','The diagram labeled a shape with five sides as a pentagon.','五边形不是六边形。'),[Q('hexagon',1,1,'A hexagon has how many sides?','six','five','eight','hexagon 有六条边。'),Q('hexagon',2,1,'A regular hexagon has?','six equal sides and six angles','four curved sides','one side only','正六边形边角规则。'),Q('hexagon',3,1,'The prefix hex- in hexagon points to?','six','two','ten','hex- 表示六。'),Q('hexagon',4,1,'Which shape is a hexagon?','a polygon with six sides','a polygon with three sides','a circle with no sides','六边形是有六边的多边形。')]);
P('hexagonal','hexagonal 由 hexagon 加形容词后缀 -al 构成，表示形状像六边形或以六边形为基础的。',C('hexagonal.s1','建筑设计','The architect chose hexagonal tiles for the courtyard, arranging them so the edges fit together without gaps.','建筑师为庭院选了六角形地砖，并把它们拼成边缘相接、不留缝隙的图案。','The architect chose hexagonal tiles for the courtyard / arranging them / so the edges fit together / without gaps.','hexagonal 修饰 tiles，表示六边形的；so 从句说明拼接效果。','瓷砖为六角形并可紧密拼接，符合 s1。'),M('The design used hexagonal tiles, each with exactly four straight sides.','The design used quadrilateral tiles, each with exactly four straight sides.','四边形有四条边，不是六角形。'),[Q('hexagonal',1,1,'A hexagonal tile is shaped like a?','six-sided polygon','four-sided polygon','perfect circle','hexagonal 表示六边形的。'),Q('hexagonal',2,1,'A honeycomb cell often has a?','hexagonal outline','five-cornered star outline','straight-line-only shape with no corners','蜂巢单元常呈六角形。'),Q('hexagonal',3,1,'The suffix -al turns hexagon into?','an adjective','a plural noun','a past-tense verb','hexagonal 是形容词。'),Q('hexagonal',4,1,'Which phrase is correct?','a hexagonal pattern','a hexagonal circle with no edges','a hexagonal five-sided figure','六角形图案可称 hexagonal pattern。')]);
P('hey','hey 是英语口语感叹词，可用于招呼、问候，也可引起他人注意；具体早期词源说法不一。',C('hey.s1','街头招呼','“Hey, Lina!” called Sam from across the station concourse, raising his hand when she turned toward the sound.','“嘿，莉娜！”萨姆在车站大厅另一边喊道；她转向声音传来的方向时，他举起了手。','“Hey, Lina!” called Sam from across the station concourse / raising his hand / when she turned toward the sound.','hey 用作呼唤语以引起莉娜注意；引号与呼号标点表现直接招呼。','说话者用 hey 叫住熟人，符合 s1。'),M('He used “hey” as a formal closing in a legal contract addressed to a judge.','He used “Dear Judge” as a formal opening in a letter addressed to a judge.','hey 是非正式招呼语，不适合当作正式法律合同的结尾称呼。'),[Q('hey',1,1,'People often say “hey” to?','call or greet someone informally','name a six-sided shape','describe a past event','hey 常用于招呼。'),Q('hey',2,1,'Which is a natural use of hey?','“Hey, are you coming with us?”','“The hexagon has six sides, hey.” in a formal report','“Hey” as a chemical formula','hey 可用于引起注意。'),Q('hey',3,1,'The tone of hey is generally?','informal and conversational','strictly ceremonial','technical and mathematical','hey 属口语感叹词。'),Q('hey',4,1,'A person calling “Hey!” may be trying to?','get someone’s attention','report a hierarchy','identify a fish','hey 可用于引人注意。')]);
P('heyday','heyday 的词源解释并不确定；现代名词指某人或事物最成功、最受欢迎的时期，也可带怀旧意味。',C('heyday.s2','行业回顾','In his memoir, the director described the studio’s heyday as a time of inventive films and lively neighborhood premieres.','导演在回忆录中把制片厂的黄金岁月描述为创意电影层出不穷、社区首映热闹非凡的时期。','In his memoir / the director described the studio’s heyday / as a time of inventive films / and lively neighborhood premieres.','heyday 指被回忆为最佳的过去时期；as 后说明那段岁月的特点。','作者怀念制片厂过去的黄金时期，符合 s2。'),M('The studio’s heyday was the period when it had never been successful, had no audience, and was about to close.','The studio’s decline was the period when it had lost its audience and was about to close.','从未成功且濒临关闭不是其全盛期。'),[Q('heyday',1,1,'A person’s heyday is?','the period when they were most successful or popular','the day they were born','a time before they began any activity','heyday 指全盛时期。'),Q('heyday',2,2,'A speaker remembering an old band’s heyday may feel?','nostalgic about its best years','certain the band has never existed','confused about a geometric shape','heyday 可指怀旧中的黄金岁月。'),Q('heyday',3,1,'Which phrase is natural?','the heyday of silent films','the heyday of a single hiccup','the heyday of a hexagon angle','heyday 常与行业、人物或活动搭配。'),Q('heyday',4,2,'A company in its heyday is at a time of?','greatest success or popularity','complete failure before opening','ordinary daily maintenance only','heyday 指成功高峰。')]);
P('hi','hi 是英语中简短、非正式的问候语，也可用来引起注意；其具体早期形成路径并不完全确定。',C('hi.s2','引起注意','“Hi, could you hold the elevator?” called Omar as the doors began to close.','电梯门开始关闭时，奥马尔喊道：“喂，能帮我按住电梯吗？”','“Hi, could you hold the elevator?” called Omar / as the doors began to close.','hi 在此用于引起陌生人的注意，随后提出请求；不是熟人间打招呼。','呼喊后接请求，体现 s2 的引起注意用法。'),M('At the start of the call, she used “hi” as a formal legal verdict declaring the case closed.','At the start of the call, she used “hi” as an informal greeting before introducing herself.','hi 是招呼语，不是法律裁决。'),[Q('hi',1,1,'“Hi” is most often?','an informal greeting','a formal court judgment','a fish species','hi 表示非正式问候。'),Q('hi',2,2,'Someone may call “Hi!” to?','attract another person’s attention','describe a high-rise building','announce a hexagon','hi 也可用于引起注意。'),Q('hi',3,1,'Which greeting is generally more informal?','hi','To whom it may concern','Your Honor','hi 属于口语问候。'),Q('hi',4,2,'In “Hi, could you help me?”, hi mainly?','gets the listener’s attention before a request','means the speaker is leaving forever','names a person’s property','hi 可先引起听者注意。')]);
P('hi-tech','hi-tech 是 high technology 的口语缩写形式，作形容词指使用新式或先进设备与技术的。',C('hi-tech.s1','制造业展览','The factory tour showed visitors a hi-tech inspection system that detected tiny defects without stopping the production line.','工厂参观向访客展示了一套高科技检测系统，它能在不停产的情况下发现微小缺陷。','The factory tour showed visitors a hi-tech inspection system / that detected tiny defects / without stopping the production line.','hi-tech 修饰 inspection system，表示使用先进技术；that 从句说明系统能力。','检测系统使用新技术完成自动检查，符合 s1。'),M('The brochure called a broken hand crank with no modern components a hi-tech inspection system.','The brochure called an automated sensor-based device a hi-tech inspection system.','完全没有现代技术的手摇装置不能称为高科技系统。'),[Q('hi-tech',1,1,'A hi-tech device uses?','new or advanced technology','only ancient hand tools','no technical equipment at all','hi-tech 表示高科技的。'),Q('hi-tech',2,1,'A hi-tech inspection system might?','use modern sensors to detect defects','depend only on a wooden sign','be a type of herring','先进传感器系统符合 hi-tech。'),Q('hi-tech',3,1,'Hi-tech is a shortened form related to?','high technology','high temperature','historical text','hi-tech 是 high technology 的缩写。'),Q('hi-tech',4,1,'Which phrase is natural?','a hi-tech laboratory','a hi-tech six-sided angle','a hi-tech herring','hi-tech 常修饰设备、系统或产业。')]);
P('hibernate','hibernate 源自拉丁语 hibernare“过冬”，指某些动物在冬季进入长时间低活动状态，也可比喻人暂时蛰居。',C('hibernate.s1','动物生态','Some bats hibernate in protected caves during the coldest months, conserving energy until insects become available again.','一些蝙蝠在最冷的月份里于受保护的洞穴中冬眠，以节省能量，直到昆虫再次出现。','Some bats hibernate in protected caves / during the coldest months / conserving energy / until insects become available again.','hibernate 描述某些动物冬季的深度休眠；conserving 补充其适应作用。','蝙蝠在冬季低活动休眠，符合 s1。'),M('The bats hibernated by remaining fully active and hunting insects every hour throughout the cold winter.','The bats remained active through the winter instead of hibernating.','整个冬天持续活跃捕猎与冬眠的低活动状态相反。'),[Q('hibernate',1,1,'Some animals hibernate by?','entering a long inactive state through winter','migrating to the moon','eating constantly without resting','hibernate 指动物冬眠。'),Q('hibernate',2,2,'A person who hibernates for a week figuratively may?','stay indoors and remain inactive','work outdoors every day','travel continuously','人比喻性 hibernate 指蛰居不动。'),Q('hibernate',3,1,'A bear may hibernate to?','conserve energy during a season of scarce food','learn to fly','change its species','冬眠能帮助动物度过食物不足的季节。'),Q('hibernate',4,2,'Which phrase is natural?','bats hibernate in winter','fish hibernate in a hallway','a hexagon hibernates','hibernate 常用于某些动物冬季休眠。')]);
P('hibernation','hibernation 由 hibernate 加 -ation 构成，指动物冬眠状态，也可比喻某项业务或活动暂时沉寂。',C('hibernation.s2','企业运营','After several quiet years, the neighborhood cinema ended its hibernation by reopening with a small independent-film festival.','沉寂数年后，社区影院以一场小型独立电影节重新开业，结束了停摆状态。','After several quiet years / the neighborhood cinema ended its hibernation / by reopening / with a small independent-film festival.','hibernation 比喻活动长期不活跃；ended ... by reopening 描述重新启动。','影院沉寂数年后重新营业，符合比喻义 s2。'),M('The business announced hibernation while expanding daily, hiring staff, and operating at full capacity without interruption.','The business remained inactive during hibernation and later reopened.','持续扩张、满负荷经营与业务处于休眠状态相矛盾。'),[Q('hibernation',1,1,'Animal hibernation is?','a deep inactive state some animals enter to survive winter','a rapid migration every afternoon','a kind of public greeting','hibernation 指动物冬眠。'),Q('hibernation',2,2,'A company’s hibernation may be?','a period when it remains quiet or inactive','a time of record daily expansion','its annual staff meeting','hibernation 可比喻活动沉寂期。'),Q('hibernation',3,1,'The phrase “come out of hibernation” means?','become active again after inactivity','enter a courtroom','begin a haircut','该短语表示沉寂后重新活跃。'),Q('hibernation',4,2,'Hibernation is related to the verb?','hibernate','hijack','hiss','hibernation 与 hibernate 同源。')]);
P('hiccup','hiccup 是模仿打嗝声形成的词，可作名词指喉部突然发出的不受控制的声音，也可比喻短暂的小问题。',C('hiccup.s2','项目进度','A brief software hiccup delayed the online booking system for ten minutes, but the team restored service before noon.','一次短暂的软件小故障使在线预订系统延迟了十分钟，但团队在中午前恢复了服务。','A brief software hiccup delayed the online booking system / for ten minutes / but the team restored service / before noon.','hiccup 比喻短暂的小问题；but 后说明故障很快解决。','系统短暂延误后恢复，符合 s2。'),M('The report called a brief ten-minute delay a permanent shutdown that would never be fixed.','The report called the brief ten-minute delay a temporary hiccup that was quickly fixed.','短暂可修复的延误不是永久停摆。'),[Q('hiccup',1,1,'A hiccup in someone’s body is?','a sudden uncontrolled sound from the throat','a long speech','a kind of fish','hiccup 指打嗝。'),Q('hiccup',2,2,'A project hiccup is?','a small temporary problem or delay','a permanent success','a formal hierarchy','hiccup 可比喻短暂小故障。'),Q('hiccup',3,3,'To hiccup means to?','make sudden involuntary throat sounds','hibernate for a season','cut wood into blocks','hiccup 也可作动词指打嗝。'),Q('hiccup',4,2,'A brief shipping hiccup would likely?','cause a short delay','end the business forever','change the product’s shape to a hexagon','hiccup 表示短暂小问题。')]);
P('hidden','hidden 是 hide 的过去分词，也作形容词，表示被藏起、不易看见或未公开的。',C('hidden.s1','寻物游戏','The children found the hidden key beneath a loose stone after following the clues left around the garden.','孩子们沿着花园里留下的线索，最后在一块松动的石头下找到了藏起来的钥匙。','The children found the hidden key / beneath a loose stone / after following the clues / left around the garden.','hidden 修饰 key，表示事先藏起来；beneath 指隐藏位置。','钥匙被放在不易发现的地方，符合 s1。'),M('The key was hidden in plain view on the table, with a large sign pointing directly to it.','The key was displayed openly on the table, with a large sign pointing directly to it.','公开摆放并有醒目标示不属于隐藏起来。'),[Q('hidden',1,1,'Something hidden is?','kept out of sight','displayed openly to everyone','already translated','hidden 表示藏起来的。'),Q('hidden',2,1,'A hidden door might be?','concealed behind a bookshelf','painted bright red in the center of a bare wall','the main entrance with a sign','隐蔽的门通常不容易看见。'),Q('hidden',3,1,'Hidden is the past participle of?','hide','hike','hinder','hidden 来自 hide。'),Q('hidden',4,1,'A hidden cost is one that?','is not immediately disclosed or noticed','is printed in large letters','does not exist at all','hidden 也可表示未公开的。')]);
P('hide','hide 源自古英语 hydan，可指把物品藏起来、让自己躲藏、隐瞒事实，也可作名词指兽皮。',C('hide.s3','调查访谈','The spokesperson refused to hide the delay from customers and posted a clear explanation of what had gone wrong.','发言人没有对客户隐瞒延误，而是清楚说明了出了什么问题。','The spokesperson refused to hide the delay from customers / and posted a clear explanation / of what had gone wrong.','hide + 事实或信息表示隐瞒；refused to 与公开解释形成对照。','发言人选择公开而不是隐瞒延误，符合 s3。'),M('The report hid the problem by describing it fully and sending the explanation to every customer.','The report disclosed the problem by describing it fully and sending the explanation to every customer.','详细说明并通知所有客户是公开信息，不是隐瞒。'),[Q('hide',1,1,'To hide a book is to?','put it somewhere it cannot easily be seen','read it aloud to everyone','turn it into a hexagon','hide 可指藏起物品。'),Q('hide',2,2,'If someone hides, they?','go somewhere so they cannot be seen','announce their location','wear a high-ranking uniform','hide 可指自己躲藏。'),Q('hide',3,3,'To hide the truth is to?','keep a fact secret','explain it publicly','prove it in a history class','hide 可指隐瞒事实。'),Q('hide',4,4,'A tanner may work with an animal hide, meaning?','its skin','its heartbeat','its habitat','hide 也可指兽皮。')]);
P('hideous','hideous 经古法语 hideus 进入英语，形容极其丑陋或令人震惊、厌恶的。',C('hideous.s1','室内设计','The reviewer called the oversized plastic statue hideous and suggested replacing it with a smaller, simpler sculpture.','评论者称那尊过大的塑料雕像丑得刺眼，并建议换成更小、更简洁的雕塑。','The reviewer called the oversized plastic statue hideous / and suggested replacing it / with a smaller, simpler sculpture.','hideous 强烈表达丑陋或令人不快；and 后提出改进建议。','评论者认为雕像极其难看，符合 s1。'),M('The reviewer described the hideous statue as beautiful and elegant in every detail.','The reviewer described the hideous statue as ugly and unpleasant to look at.','beautiful and elegant 与 hideous 的负面含义相反。'),[Q('hideous',1,1,'Something hideous is?','extremely ugly or shocking','perfectly ordinary and pleasant','six-sided','hideous 表示丑恶、令人震惊。'),Q('hideous',2,1,'Which might be called hideous?','a grotesque object that disgusts viewers','a graceful sculpture admired by everyone','a useful hint','极其难看的物体可称 hideous。'),Q('hideous',3,1,'Hideous is closest in meaning to?','horrible or very ugly','beautiful','hesitant','hideous 与 horrible、ugly 接近。'),Q('hideous',4,1,'A hideous smell would be?','extremely unpleasant','fresh and fragrant','inaudible','hideous 也可形容令人厌恶的事物。')]);
P('hierarchical','hierarchical 由 hierarchy 加 -ical 构成，表示按地位、权力或类别分成不同等级的。',C('hierarchical.s1','组织管理','The company has a hierarchical approval process: team leads review requests first, and executives decide on the largest expenses.','公司有一套分级审批流程：先由团队主管审核申请，再由高管决定金额最大的支出。','The company has a hierarchical approval process / team leads review requests first / and executives decide / on the largest expenses.','hierarchical 修饰 approval process，表示依等级逐层处理；冒号后举例说明层级。','决定权依岗位等级分层安排，符合 s1。'),M('The organization was hierarchical because every member had exactly the same authority and there were no levels.','The organization was flat because every member had the same authority and there were no levels.','没有任何等级差异的组织不是 hierarchical。'),[Q('hierarchical',1,1,'A hierarchical system is organized?','in ranked levels','with no differences in level','by random weather','hierarchical 表示分等级的。'),Q('hierarchical',2,1,'A hierarchical workplace may have?','junior staff, managers, and executives at different levels','only one role shared by everyone','no reporting structure','不同岗位层级构成等级组织。'),Q('hierarchical',3,1,'The suffix -ical in hierarchical forms an?','adjective','adverb','past-tense verb','hierarchical 是形容词。'),Q('hierarchical',4,1,'A hierarchical approval process sends a request?','through levels of authority','to every person at random','only to a customer','分级流程按权力层级审批。')]);
P('hierarchy','hierarchy 源自希腊语 hierarkhia“祭司的统治”，现指地位或权力分级的体系、组织高层，或按层次排列的结构。',C('hierarchy.s3','信息分类','The library’s hierarchy of topics moves from broad subjects to narrower categories, helping readers locate a specific field.','图书馆的主题层次从宽泛学科逐步细分到更具体的类别，帮助读者定位特定领域。','The library’s hierarchy of topics moves from broad subjects / to narrower categories / helping readers locate / a specific field.','hierarchy 指按层级排列的结构；from ... to ... 展示由宽到窄的层次。','主题按层次分门别类，符合 s3。'),M('The library’s hierarchy placed every topic on one flat level with no categories or subdivisions.','The library’s list placed every topic on one flat level with no categories or subdivisions.','没有层次或分类的平面列表不是 hierarchy。'),[Q('hierarchy',1,1,'A social hierarchy is?','a system ranking people by status or authority','a fish swimming in a school','a sudden pause in speech','hierarchy 可指社会等级体系。'),Q('hierarchy',2,2,'An organization’s hierarchy may refer to?','the people at its upper levels','every customer outside it','its weather forecast','hierarchy 也可指组织领导层。'),Q('hierarchy',3,3,'A hierarchy of topics arranges them?','in levels or categories','in one unordered pile','by the number of hiccups','hierarchy 可指分层结构。'),Q('hierarchy',4,1,'The word’s historical root relates to?','rule by a high priest','a fish market','a six-sided shape','hierarchy 源自与祭司统治相关的希腊语。')]);
P('hieratic','hieratic 源自希腊语 hieratikos“祭司的”，可指祭司或庄严仪式风格，也指古埃及僧侣书写体。',C('hieratic.s2','古埃及文字','The curator explained that the papyrus was written in hieratic, a flowing Egyptian script used alongside monumental hieroglyphs.','策展人解释说，这份纸莎草文书使用僧侣体书写，这是一种与纪念碑象形文字并用的流畅埃及文字。','The curator explained that the papyrus was written in hieratic / a flowing Egyptian script / used alongside monumental hieroglyphs.','hieratic 作名词性术语指古埃及僧侣体；同位语说明这种书写体。','流畅书写体与纪念性象形文字相区别，符合 s2。'),M('The papyrus was written in hieratic, the same monumental picture script carved only into stone walls.','The papyrus was written in hieratic, a cursive script distinct from monumental hieroglyphs.','僧侣体是流畅书写体，不是只刻在石墙上的纪念性象形文字。'),[Q('hieratic',1,1,'A hieratic style may be?','formal and priestly in character','casual and slang-filled','a type of fish','hieratic 可形容祭司式或庄严风格。'),Q('hieratic',2,2,'Ancient Egyptian hieratic is?','a cursive script distinct from hieroglyphs','a modern computer font only','a spoken language with no writing','hieratic 可指古埃及僧侣书写体。'),Q('hieratic',3,1,'The root hier- in hieratic relates to?','sacred or priestly matters','six sides','human hair','hieratic 与祭司、神圣相关。'),Q('hieratic',4,2,'A hieratic papyrus is likely?','written in an ancient Egyptian cursive script','a plastic object from a modern factory','a history of herring','僧侣体常写于纸莎草文书。')]);
P('hieroglyph','hieroglyph 经法语源自希腊语 hieroglyphika“神圣雕刻”，指书写系统中用作文字的图画字符，尤指古埃及字符。',C('hieroglyph.s1','考古展览','A carved hieroglyph showed a bird beside the ruler’s name, and the guide explained how the image represented a sound.','一枚雕刻的象形文字在统治者姓名旁画着一只鸟，导览员解释了这个图像如何表示一个声音。','A carved hieroglyph showed a bird beside the ruler’s name / and the guide explained / how the image represented a sound.','hieroglyph 指图画字符；how 从句说明图形在文字系统中的作用。','鸟形图像作为文字字符表示语音，符合 s1。'),M('The guide called an ordinary alphabetic letter a hieroglyph even though it was not a stylized picture character.','The guide called the stylized picture character a hieroglyph.','普通字母并非此处所说的图画字符。'),[Q('hieroglyph',1,1,'A hieroglyph is?','a stylized picture used as a writing character','a kind of high-rise building','a fish caught in the sea','hieroglyph 指图画字符。'),Q('hieroglyph',2,1,'Ancient Egyptian hieroglyphs were often?','carved or painted picture-like characters','spoken greetings only','modern highway signs only','古埃及象形文字常以图画字符呈现。'),Q('hieroglyph',3,1,'A single hieroglyph may represent?','a word, sound, or idea in a writing system','a whole city’s weather','a person’s hairdo','象形字符可表示语音、词或观念。'),Q('hieroglyph',4,1,'The Greek element glyph relates to?','writing or carving','hiking','hibernation','glyph 与书写、刻写有关。')]);
P('hieroglyphic','hieroglyphic 由 hieroglyph 加 -ic 构成，可作名词指象形文字书写，也可作形容词表示以象形字符书写的。',C('hieroglyphic.s2','展品说明','The museum displayed a hieroglyphic inscription beside a translation, allowing visitors to compare the ancient signs with their meaning.','博物馆把一段象形文字铭文与译文并列展示，让访客比较古代符号及其含义。','The museum displayed a hieroglyphic inscription beside a translation / allowing visitors to compare / the ancient signs / with their meaning.','hieroglyphic 修饰 inscription，表示以象形文字书写的；allowing 补充展示效果。','铭文由象形字符写成，符合形容词义 s2。'),M('The museum labeled a paragraph written entirely in ordinary modern English as hieroglyphic.','The museum labeled the picture-based ancient inscription as hieroglyphic.','用普通现代英语字母书写的段落不属于象形文字书写。'),[Q('hieroglyphic',1,1,'Hieroglyphic writing uses?','picture-like characters as part of a writing system','only spoken sounds with no symbols','a hierarchy of office ranks','hieroglyphic 指象形文字书写。'),Q('hieroglyphic',2,2,'A hieroglyphic inscription is?','written in or related to hieroglyphs','a modern highway made of asphalt','a high-ranking official','hieroglyphic 可作形容词。'),Q('hieroglyphic',3,1,'Hieroglyphic can also name?','a passage written in hieroglyphs','a six-sided tile','a herring school','hieroglyphic 可作名词指象形文字文本。'),Q('hieroglyphic',4,2,'Which phrase is natural?','hieroglyphic symbols','hieroglyphic herring soup','hieroglyphic hairdresser','hieroglyphic 常修饰文字和铭文。')]);
P('high','high 源自古英语 hēah，可指垂直位置高、数量或程度大、地位高、声音尖，也可作名词指高处或高点。',C('high.s4','音乐制作','The engineer lowered the high note in the mix because it was piercing through the singer’s softer vocal line.','工程师调低了混音中的高音，因为它盖过了歌手较轻柔的人声。','The engineer lowered the high note in the mix / because it was piercing through / the singer’s softer vocal line.','high 修饰 note，指音高接近音域上端；because 说明调低音量的原因。','该音处于较高音域，符合 s4。'),M('The singer produced a high note at the bottom of the vocal range, lower than every other sound.','The singer produced a low note at the bottom of the vocal range.','音域底部的声音是低音，不是 high note。'),[Q('high',1,1,'A high mountain peak is?','far above the surrounding land','close to sea level','a low valley','high 可表示位置高。'),Q('high',2,2,'A high temperature is?','great in amount or degree','near zero in every context','a person’s rank','high 可表示程度或数量大。'),Q('high',3,3,'A high official is?','senior in position or rank','low in authority','a fish in a school','high 可表示地位等级高。'),Q('high',4,4,'A high-pitched voice sounds?','near the upper end of the sound range','deep and low','silent','high 可形容高音。')]);
P('high point','high point 是固定复合名词，指经历、活动或故事中最精彩、最令人满意的时刻。',C('high point.s1','旅行回忆','The high point of the trip was watching the sunrise from the ridge after a quiet overnight hike.','这趟旅行最精彩的时刻，是夜间安静徒步后在山脊上观看日出。','The high point of the trip was watching the sunrise / from the ridge / after a quiet overnight hike.','the high point of + 活动表示其最精彩部分；was 后用动名词短语作表语。','日出被描述为整趟旅行中最精彩的时刻，符合 s1。'),M('The traveler called the high point of the trip its least enjoyable and most disappointing moment.','The traveler called the low point of the trip its least enjoyable moment.','最令人失望的时刻是 low point，不是 high point。'),[Q('high point',1,1,'The high point of an event is?','its best or most exciting moment','its lowest physical location','its final bill','high point 指最精彩的时刻。'),Q('high point',2,1,'The high point of a concert might be?','the most memorable performance','the quiet walk to the empty parking lot','the ticket number','最难忘的演出可以是音乐会高潮。'),Q('high point',3,1,'Which phrase is natural?','the high point of the season','the high point of a low note only','the high point of a hiccup','high point 常与经历或活动搭配。'),Q('high point',4,1,'The closest opposite of high point is?','low point','best moment','highlight','low point 表示低谷。')]);
P('high-end','high-end 由 high 与 end 组成，作形容词表示价格较高、品质优良或定位高端的。',C('high-end.s1','产品比较','The shop specializes in high-end cameras with durable lenses and professional controls for experienced photographers.','这家商店专营高端相机，配有耐用镜头和供资深摄影师使用的专业控制功能。','The shop specializes in high-end cameras / with durable lenses / and professional controls / for experienced photographers.','high-end 修饰 cameras，表示高价位或高品质定位；with 短语列出特点。','专业功能与优质配置体现高端产品定位。'),M('The catalog called its cheapest disposable camera high-end, although it had basic parts and no advanced features.','The catalog called its cheapest disposable camera an entry-level model because it had basic parts.','基础、廉价且无高级功能的相机不符合 high-end 定位。'),[Q('high-end',1,1,'A high-end product is usually?','expensive and of fine quality','the cheapest item available','made without any features','high-end 表示高端的。'),Q('high-end',2,1,'A high-end restaurant is likely to be?','costly and refined','a free roadside stall','a school hallway','高端餐厅通常定位较高、品质精良。'),Q('high-end',3,1,'Which item could be called high-end?','a premium camera with professional controls','a broken toy with missing parts','a blank paper bag','高品质专业相机可称 high-end。'),Q('high-end',4,1,'High-end most directly describes?','a market or quality level','a sound’s pitch','a person’s pronoun','high-end 描述产品定位和品质档次。')]);
P('high-ranking','high-ranking 由 high 与 ranking 组成，指在组织或体系中职位、级别较高的。',C('high-ranking.s1','公共机构','A high-ranking official met with neighborhood representatives to explain the new transit plan and answer their questions.','一位高级官员会见社区代表，解释新的交通计划并回答他们的问题。','A high-ranking official met with neighborhood representatives / to explain the new transit plan / and answer their questions.','high-ranking 修饰 official，表示其在组织中级别较高；to explain 并列说明会面的目的。','该官员负责向社区说明计划，符合高级别义。'),M('The high-ranking officer held the lowest position in the department and had no authority over anyone.','The junior officer held the lowest position in the department and had no authority over anyone.','组织中职位最低、没有管理权的人不是 high-ranking。'),[Q('high-ranking',1,1,'A high-ranking employee is?','senior in position or authority','new to the organization and at the lowest level','a high-pitched singer','high-ranking 指高级别的。'),Q('high-ranking',2,1,'A high-ranking official may?','lead a department or make senior decisions','have no role or authority at all','sell fish at a market','高级官员通常承担较高职责。'),Q('high-ranking',3,1,'Which phrase is natural?','a high-ranking diplomat','a high-ranking herring','a high-ranking hallway','该词常修饰职位或人员。'),Q('high-ranking',4,1,'The closest opposite of high-ranking is?','junior','senior','powerful','junior 表示级别较低。')]);
P('high-rise','high-rise 由 high 与 rise 组成，作名词指有很多层的高层建筑，也可作定语修饰此类建筑。',C('high-rise.s1','城市规划','The new high-rise will include apartments above the shops and a public courtyard at street level.','这座新高层建筑将在商铺上方设置公寓，并在街道层设一个公共庭院。','The new high-rise will include apartments above the shops / and a public courtyard / at street level.','high-rise 作名词指高层建筑；above 与 at street level 对比不同楼层的用途。','多层公寓大楼符合高层建筑义。'),M('The city described a single-story garden shed as a high-rise building.','The city described a thirty-story apartment tower as a high-rise building.','只有一层的棚屋不是高层建筑。'),[Q('high-rise',1,1,'A high-rise is?','a very tall building with many floors','a small one-story shed','a narrow mountain trail','high-rise 指高层建筑。'),Q('high-rise',2,1,'A high-rise apartment block may have?','many stories above street level','only one room underground','no floors at all','高层公寓楼有多层。'),Q('high-rise',3,1,'Which phrase is natural?','a high-rise office tower','a high-rise herring','a high-rise haircut','high-rise 常修饰建筑。'),Q('high-rise',4,1,'The word rise refers to a building’s?','upward height','price only','history','high-rise 指向上高耸的建筑。')]);
P('high-school','high-school 由 high 与 school 组成，作形容词表示与青少年就读的中学阶段有关。',C('high-school.s1','教育经历','She joined the high-school debate team in tenth grade and later coached younger students at the same school.','她在十年级时加入高中辩论队，后来又在同一所学校指导低年级学生。','She joined the high-school debate team / in tenth grade / and later coached younger students / at the same school.','high-school 修饰 debate team，表示学校阶段；in tenth grade 提供年级语境。','辩论队属于高中阶段的学校活动，符合 s1。'),M('The high-school student was a toddler who had not yet entered any school.','The preschool child was a toddler who had not yet entered high school.','尚未入学的幼儿不是高中生。'),[Q('high-school',1,1,'High-school students are generally?','teenagers attending secondary school','preschool children','retired university professors','high-school 指高中阶段的。'),Q('high-school',2,1,'A high-school reunion brings together?','former students from a secondary school','people who attended the same gym today','a group of herring','高中同学聚会是昔日中学同学重聚。'),Q('high-school',3,1,'Which phrase is natural?','a high-school science class','a high-school fish','a high-school hieroglyph','high-school 常作定语修饰课程或学生。'),Q('high-school',4,1,'High-school is associated with?','education for teenagers before college','elementary school only','a type of building height','该词指青少年中学阶段。')]);
P('high-tech','high-tech 是 high technology 的缩写，可形容使用最新技术的事物，也可形容外观具有现代科技感的风格。',C('high-tech.s2','展厅设计','The visitor center has a high-tech appearance, with glowing panels and digital maps even though its exhibits are mostly historical.','游客中心外观看起来很有科技感，配有发光面板和数字地图，尽管展品大多与历史有关。','The visitor center has a high-tech appearance / with glowing panels and digital maps / even though its exhibits / are mostly historical.','high-tech 在此形容外观风格；even though 表示外观与展品内容形成对照。','发光面板和数字地图带来现代技术感，符合 s2。'),M('The room had a high-tech appearance despite containing only blank walls, no equipment, and no modern design features.','The room had a plain appearance, with blank walls and no modern design features.','没有设备或现代设计特征的房间不显得高科技。'),[Q('high-tech',1,1,'A high-tech appearance is?','a modern, technical-looking style','a purely medieval decoration','a low-ranking office','high-tech 可形容科技感外观。'),Q('high-tech',2,2,'A high-tech lobby may feature?','digital displays and glowing interactive panels','only handwritten signs on rough wood','a herring net','数字显示屏可营造高科技外观。'),Q('high-tech',3,1,'In another sense, high-tech equipment uses?','the most modern technology','no tools or machines','only ancient stone carvings','high-tech 也指使用先进技术。'),Q('high-tech',4,2,'High-tech is related to the phrase?','high technology','high school','higher education only','high-tech 是 high technology 的缩写。')]);
P('higher','higher 是 high 的比较级，表示位置、程度、数量或等级比另一对象更高。',C('higher.s1','建筑测量','The new observation deck sits higher than the old platform, giving visitors a clearer view over the harbor.','新的观景台比旧平台更高，让访客能更清楚地俯瞰港湾。','The new observation deck sits higher than the old platform / giving visitors a clearer view / over the harbor.','higher than 用于比较两个位置的高度；giving 补充高度带来的效果。','观景台位置超过旧平台，符合比较级义。'),M('The lower platform was higher than the tower roof even though it stood below it.','The upper platform was higher than the lower tower roof.','若平台实际位于屋顶以下，就不能说它比屋顶更高。'),[Q('higher',1,1,'Higher is the comparative form of?','high','highest','heighten','higher 是 high 的比较级。'),Q('higher',2,1,'If one shelf is higher than another, it is?','farther up','farther down','the same height','higher 表示位置更高。'),Q('higher',3,1,'A higher price is?','greater than another price','always lower than every price','a person’s rank only','higher 可表示数量或程度更大。'),Q('higher',4,1,'Which phrase is correct?','higher than the previous level','higher as the previous level','highest than the previous level','比较级常用 higher than。')]);
P('highest','highest 是 high 的最高级，表示在比较范围中位置、程度或等级最高的。',C('highest.s1','山地旅行','At 3,400 meters, the refuge is the highest staffed shelter on the route and the last place to refill water.','这座海拔三千四百米的避难所是这条路线上海拔最高的有人值守庇护点，也是最后一个补水处。','At 3,400 meters / the refuge is the highest staffed shelter on the route / and the last place / to refill water.','highest 是最高级，表示同一比较范围内最高；on the route 限定比较范围。','与路线上的其他有人值守庇护点相比，它海拔最高。'),M('The lowest shelter on the route was described as the highest despite being below every other shelter.','The lowest shelter on the route was described as the lowest because it was below every other shelter.','低于所有其他庇护点的位置应称最低，而不是最高。'),[Q('highest',1,1,'Highest is the superlative form of?','high','higher','height','highest 是 high 的最高级。'),Q('highest',2,1,'The highest point in a range is?','above all the other points','below every other point','exactly halfway down','highest 表示最高处。'),Q('highest',3,1,'A highest score is?','the greatest score among those compared','lower than every other score','an average score','最高分大于比较范围中的其他分数。'),Q('highest',4,1,'Which phrase is correct?','the highest building in town','the higher building of all three','the most high building','highest 是最高级形式。')]);
P('highjack','highjack 是 hijack 的较少见拼法，词典收录为强行夺取飞机、车辆或活动控制权；通常拼作 hijack。',C('highjack.s1','拼写辨析','The archived newspaper used the spelling highjack in its report that a bus had been seized, while current coverage usually spells the verb hijack.','档案报纸在报道一辆公交车遭强行控制时使用了 highjack 这一拼法，而当今报道通常把这个动词拼作 hijack。','The archived newspaper used the spelling highjack / in its report that a bus had been seized / while current coverage / usually spells the verb hijack.','highjack 在这里是词条所收的变体拼写；现代更常见的拼法是 hijack。','旧报使用该变体描述强行夺取车辆控制权，符合 s1。'),M('The copy editor changed hijack to highjack because highjack is the only accepted spelling in modern English.','The copy editor kept hijack, the usual modern spelling, and noted highjack as a less common variant.','把 highjack 说成唯一标准拼法，与常见拼法为 hijack 不符。'),[Q('highjack',1,1,'Highjack is recorded as?','a less common spelling variant of hijack','the only accepted modern spelling','a word for a six-sided shape','词典提示常用拼法是 hijack。'),Q('highjack',2,1,'The verb highjack refers to?','taking control of a vehicle or event by force','greeting someone casually','raising a fee slightly','highjack 可指强行夺取控制权。'),Q('highjack',3,1,'Which spelling is more usual today?','hijack','highjack only','high-jack always','通常拼作 hijack。'),Q('highjack',4,1,'An editor seeing highjack in an old clipping may?','recognize it as a variant spelling of hijack','assume it means “high school”','correct it to herring','highjack 是 hijack 的变体拼法。')]);
P('highland','highland 由 high 与 land 组成，指周围地势较高的地区，也可专指苏格兰北部的山区。',C('highland.s2','苏格兰地理','The tour followed a narrow road through the Scottish Highlands, stopping at villages surrounded by open moor and rugged hills.','旅行沿着狭窄公路穿过苏格兰高地，并在四周环绕着开阔荒原和崎岖山丘的村庄停留。','The tour followed a narrow road through the Scottish Highlands / stopping at villages / surrounded by open moor / and rugged hills.','the Scottish Highlands 是专名，指苏格兰北部山区；through 表示穿行其间。','路线位于苏格兰北部山区，符合 s2。'),M('The guide described the Scottish Highlands as a flat coastal plain below sea level.','The guide described the Scottish Highlands as a mountainous northern region.','崎岖高地不是低于海平面的平坦沿海平原。'),[Q('highland',1,1,'A highland is?','an area higher than the land around it','a deep flat ocean trench','a crowded city hallway','highland 指高地。'),Q('highland',2,2,'The Scottish Highlands are?','a mountainous region in northern Scotland','a desert in southern Spain','a part of a gymnasium','该词也特指苏格兰高地。'),Q('highland',3,1,'A highland landscape is likely to have?','elevated terrain and hills','only low wetlands','no land at all','高地地形高于周边地区。'),Q('highland',4,2,'The word combines high with?','land','rank','way','highland 由 high 与 land 构成。')]);
P('highlight','highlight 由 high 与 light 构成，可作动词表示强调或标色，也可作名词指最精彩部分或头发挑染。',C('highlight.s3','展览导览','The highlight of the exhibition was a restored telescope that visitors could examine through a glass case.','展览最精彩的部分是一架修复好的望远镜，访客可以隔着玻璃展柜仔细观看。','The highlight of the exhibition was a restored telescope / that visitors could examine / through a glass case.','the highlight of 指活动或展览中最吸引人的部分；that 从句说明参观方式。','望远镜是展览中最精彩、最值得看的部分，符合 s3。'),M('The guide called the broken display case the exhibition’s highlight even though visitors found it dull and irrelevant.','The guide called the restored telescope the exhibition’s highlight because visitors found it fascinating.','无趣且无关的破损展柜不能合理称作展览的亮点。'),[Q('highlight',1,1,'To highlight an important point is to?','draw attention to it','hide it completely','make it less visible','highlight 作动词可表示强调。'),Q('highlight',2,2,'To highlight a line in a book is to?','mark it with color','erase it from the page','read it aloud only','highlight 可表示用颜色标出。'),Q('highlight',3,3,'The highlight of a trip is?','its best or most interesting part','its least successful moment','the ticket price','highlight 可作名词指精彩部分。'),Q('highlight',4,4,'Hair highlights are?','lightened streaks in the hair','a haircut appointment','a type of hibernation','highlight 也指挑染的发束。')]);
P('highly','highly 由 high 加副词后缀 -ly 构成，表示程度很高，也可表示赞许地、评价很高地。',C('highly.s2','职业评价','The historian is highly regarded by colleagues for careful archival research and clear explanations of uncertain evidence.','这位历史学家因细致的档案研究和对不确定证据的清晰解释而受到同行高度赞誉。','The historian is highly regarded by colleagues / for careful archival research / and clear explanations / of uncertain evidence.','highly regarded 表示受到高度评价；for 引出受到赞誉的原因。','同行给予很高评价，符合 s2。'),M('The committee highly praised the report by condemning it as careless and useless.','The committee strongly criticized the report as careless and useless.','称报告粗疏无用是批评，不是赞许。'),[Q('highly',1,1,'Highly can mean?','to a great degree','not at all','at the exact middle','highly 可表示程度很高。'),Q('highly',2,2,'A highly praised book is?','admired and spoken of favorably','strongly condemned by readers','hidden from every reader','highly 可表示赞许地。'),Q('highly',3,1,'Which phrase is natural?','highly effective','highly six-sided','highly herring','highly 常修饰形容词表示程度很高。'),Q('highly',4,2,'“She speaks highly of him” means she?','expresses a good opinion of him','speaks in a very high voice only','refuses to mention him','speak highly of 表示高度赞扬。')]);
P('highway','highway 源自古英语 heahweg“主路”，指连接地区的主要公路，也可泛指主要陆路、水路或航线。',C('highway.s1','公路出行','The highway between the two cities was closed for repairs, so drivers followed a signed detour through nearby towns.','两座城市之间的主干公路因维修封闭，因此司机按路标绕行附近城镇。','The highway between the two cities was closed for repairs / so drivers followed a signed detour / through nearby towns.','highway 指城市间主要公路；so 引出道路关闭后的绕行结果。','连接城市的主干道封闭维修，符合 s1。'),M('The map labeled a narrow private garden path used by one household as the main public highway between cities.','The map labeled the wide public road connecting the cities as the highway.','仅供一户使用的私家园路不是连接城市的公共主干道。'),[Q('highway',1,1,'A highway is usually?','a main public road connecting places','a hallway inside one house','a small hillock','highway 指主干公路。'),Q('highway',2,2,'A sea highway can mean?','a major route used by ships','a road made only for bicycles','a flight of stairs','highway 也可泛指水上主要通道。'),Q('highway',3,1,'A highway authority may be?','an agency responsible for major roads','a group of herring','a hair salon','highway 也出现在公路管理机构名称中。'),Q('highway',4,2,'Which phrase is natural?','a highway between two cities','a highway inside a person’s hair','a highway of guilt','highway 常指连接地区的主路。')]);
P('hijack','hijack 的词源细节并不完全确定；现代义包括强行夺取车辆控制权、操纵讨论，也可作名词指劫持行为。',C('hijack.s2','会议秩序','One speaker tried to hijack the budget meeting by ignoring the agenda and arguing only for his own proposal.','一位发言者试图强行控制预算会议，无视议程，只为自己的提案争辩。','One speaker tried to hijack the budget meeting / by ignoring the agenda / and arguing only / for his own proposal.','hijack 在此比喻不公平地控制会议或讨论；by 引出控制方式。','发言者挟持会议议程为自己争取利益，符合 s2。'),M('The chair hijacked the meeting by following the agenda fairly and giving every participant equal time.','The chair guided the meeting fairly by following the agenda and giving every participant equal time.','公平遵循议程并给所有人发言机会不是不公平地劫持讨论。'),[Q('hijack',1,1,'To hijack a plane is to?','seize control of it by force','book a seat on it','repair its engine','hijack 可指强行劫持飞机。'),Q('hijack',2,2,'To hijack a discussion is to?','take it over unfairly for one’s own purpose','keep it balanced and on agenda','write down everyone’s ideas neutrally','hijack 可比喻不公平地主导讨论。'),Q('hijack',3,3,'A hijack can also be?','an act of taking control by force','a type of six-sided figure','a period of hibernation','hijack 可作名词指劫持行为。'),Q('hijack',4,1,'Which action might hijack a meeting?','one participant derails it to push a private agenda','the chair gives all sides equal time','a secretary records the minutes','挟持讨论以推个人议程属于 hijack。')]);
P('hike','hike 词源早期来源不确定；现代可指乡间长途徒步，也可作名词或动词表示价格、费率大幅上涨或提高。',C('hike.s4','公共收费','The council voted to hike parking fees next year, citing the rising cost of maintaining the city’s garages.','市议会投票决定明年大幅提高停车费，理由是维护市政停车场的成本不断上升。','The council voted to hike parking fees next year / citing the rising cost / of maintaining the city’s garages.','hike fees 是及物用法，表示大幅提高费率；citing 补充提高的理由。','停车费被提高手段是收费上涨，符合 s4。'),M('The council hiked parking fees by lowering them from ten dollars to five dollars per day.','The council cut parking fees by lowering them from ten dollars to five dollars per day.','把费用从十元降到五元是削减，不是提高。'),[Q('hike',1,1,'To hike in the countryside is to?','take a long walk for pleasure','drive a bus on a highway','hide an object','hike 可指徒步旅行。'),Q('hike',2,2,'A weekend hike is?','a long walk, often outdoors','a raised parking fee','a haircut style','hike 可作名词指徒步活动。'),Q('hike',3,3,'A price hike is?','a large increase in price','a reduction in price','a person’s high rank','price hike 指价格大幅上涨。'),Q('hike',4,4,'To hike a tax is to?','raise it sharply','halve it','hide it from records','hike 可作动词表示大幅提高。')]);
P('hiker','hiker 由 hike 加施事者后缀 -er 构成，指进行乡间长途步行或徒步旅行的人。',C('hiker.s1','山径安全','Each hiker carried a map and enough water for the exposed section of trail above the tree line.','每位徒步者都带着地图和足够的水，以应对林线以上无遮蔽的路段。','Each hiker carried a map / and enough water / for the exposed section of trail / above the tree line.','hiker 指徒步旅行者；each 后接单数名词与 carried 搭配。','沿步道远足并准备地图、水的人是 hiker。'),M('The hiker spent the day driving a taxi through downtown and never walked on a trail.','The taxi driver spent the day driving through downtown and never walked on a trail.','整天开车而没有徒步的人不是 hiker。'),[Q('hiker',1,1,'A hiker is someone who?','takes long walks in the countryside','studies only ancient scripts','works as a historian','hiker 指徒步者。'),Q('hiker',2,1,'A hiker on a remote trail should carry?','water and a route map','a concert hall','a hairdryer only','徒步者常带水和地图。'),Q('hiker',3,1,'The suffix -er in hiker refers to?','a person who hikes','a place where hikes end','a past action','-er 表示从事徒步的人。'),Q('hiker',4,1,'Which person is a hiker?','someone walking a long country trail for pleasure','someone commuting only by elevator','someone editing a book at home','沿乡间路线长途步行的人是徒步者。')]);
P('hilarious','hilarious 源自拉丁语 hilaris“欢快的”，形容非常好笑、能引人大笑的。',C('hilarious.s1','喜剧演出','The comedian’s story about a runaway garden hose was so hilarious that the audience kept laughing through the next act.','喜剧演员讲的一段关于失控花园水管的故事非常好笑，观众在下一幕开始时还一直笑。','The comedian’s story about a runaway garden hose was so hilarious / that the audience kept laughing / through the next act.','hilarious 表示极好笑；so ... that 引出观众大笑的结果。','听众持续大笑说明故事十分好笑，符合 s1。'),M('The audience called the hilarious performance boring and not funny, saying it had no jokes at all.','The audience called the dull performance boring and not funny, saying it had no jokes at all.','若观众全程没有发笑，就不支持 hilarious 的评价。'),[Q('hilarious',1,1,'A hilarious story is?','extremely funny','deeply frightening','historically accurate only','hilarious 表示非常好笑。'),Q('hilarious',2,1,'A hilarious comedy may make people?','laugh loudly','fall asleep from boredom','feel a sudden gust','极好笑的喜剧会使人发笑。'),Q('hilarious',3,1,'Which phrase is natural?','a hilarious joke','a hilarious hexagon angle','a hilarious highway sign meaning “stop”','hilarious 常修饰笑话或表演。'),Q('hilarious',4,1,'The closest meaning of hilarious is?','very funny','slightly hesitant','highly ranked','very funny 与 hilarious 接近。')]);
P('hilarity','hilarity 由 hilar-“欢快”词根加名词后缀 -ity 构成，指大声欢笑、热闹欢闹，也可指欢乐的气氛。',C('hilarity.s2','聚会氛围','A burst of hilarity filled the kitchen when the cousins began acting out the family’s old stories.','表兄妹们开始演绎家族旧事时，厨房里顿时充满欢乐热闹的气氛。','A burst of hilarity filled the kitchen / when the cousins began acting out / the family’s old stories.','hilarity 在此指欢乐热闹的气氛；when 从句说明气氛出现的缘由。','众人表演旧事带来欢快气氛，符合 s2。'),M('The room was filled with hilarity while everyone remained silent, tense, and unhappy.','The room was filled with tension while everyone remained silent and unhappy.','沉默紧张、心情不快的气氛不是 hilarity。'),[Q('hilarity',1,1,'Hilarity may refer to?','loud laughter and cheerful noise','a secret hierarchy','a sudden highway fee','hilarity 可指欢笑和欢闹。'),Q('hilarity',2,2,'A room filled with hilarity has?','a happy, excited atmosphere','a silent and gloomy mood','a high-ranking official','hilarity 也指欢乐气氛。'),Q('hilarity',3,1,'Which scene creates hilarity?','friends laughing together at a comic story','guests sitting silently after bad news','a hiker lost in a storm','共同欢笑会形成 hilarity。'),Q('hilarity',4,2,'Hilarity is closest to?','merriment','hesitation','hibernation','merriment 表示欢快。')]);
P('hill','hill 源自古英语 hyll，可指低于高山的隆起地形、道路斜坡，也可在美国口语中代指国会山或联邦政府。',C('hill.s2','道路驾驶','The delivery van struggled up the steep hill, so the driver shifted into a lower gear before the next bend.','送货车吃力地爬上陡坡，因此司机在下一个弯道前换入低档。','The delivery van struggled up the steep hill / so the driver shifted into a lower gear / before the next bend.','hill 在此指道路斜坡；up the hill 表示沿坡向上行驶。','车辆爬的是道路坡面，对应 s2。'),M('The van rolled downhill while the driver described the level road as a steep hill.','The van climbed the steep hill while the driver described the rising road accurately.','完全平坦的道路不是陡坡。'),[Q('hill',1,1,'A hill is?','raised land smaller than a mountain','a flat ocean floor','a type of hieroglyph','hill 指小山、山丘。'),Q('hill',2,2,'A steep hill on a road is?','a slope vehicles must climb or descend','a dormitory building','a fish market','hill 可指道路斜坡。'),Q('hill',3,3,'In US political news, the Hill may refer to?','the Capitol or the federal government','a garden hose','a type of herring','the Hill 可代指美国国会山或政府。'),Q('hill',4,1,'A small raised area of land is a?','hill','highway','hiss','hill 指小山丘。')]);
P('hillbilly','hillbilly 是 hill 与人名 Billy 组合而来的美国俚语贬称，指美国南部山区的乡村居民；该词带冒犯性，不宜中性称人。',C('hillbilly.s1','编辑审稿','The editor removed the word “hillbilly” from the character description, noting that it is derogatory and replacing it with a precise, respectful description of the setting.','编辑从人物介绍中删去了“hillbilly”一词，指出它带有贬义，并改用具体、尊重的环境描述。','The editor removed the word “hillbilly” from the character description / noting that it is derogatory / and replacing it / with a precise, respectful description of the setting.','此处是在讨论带冒犯性的标签；描述具体地区或生活背景通常比使用贬称更合适。','编辑识别出该词的贬义并改写，符合 source entry 的用法说明。'),M('The style guide recommends hillbilly as a respectful, neutral label for every rural person in the United States.','The style guide notes that hillbilly is derogatory and recommends a specific, respectful description instead.','该词是贬称，不适合作为对所有乡村居民的中性称呼。'),[Q('hillbilly',1,1,'Hillbilly is described in this entry as?','a derogatory label for a rural mountain person, especially in the southern US','a universally respectful formal title','a kind of raised land','词条明确提示其为贬称。'),Q('hillbilly',2,1,'A careful contemporary writer should?','avoid using hillbilly as a neutral label for people','apply it to anyone from a rural area','use it as a formal job title','由于带有冒犯性，不应当作中性标签。'),Q('hillbilly',3,1,'Which replacement is more respectful in a factual description?','a specific regional or rural description','a broader insulting label','a made-up medical diagnosis','具体描述比贬称更尊重。'),Q('hillbilly',4,1,'The word hillbilly is primarily?','a derogatory term','a neutral word for a hill','a scientific fish name','hillbilly 是带贬义的称呼。')]);
P('hillock','hillock 由 hill 加 diminutive 后缀 -ock 构成，指小山丘或小土丘。',C('hillock.s1','乡间景色','A lone oak stood on the hillock above the meadow, visible from the footpath that crossed the valley.','草地上方的小山丘上长着一棵孤零零的橡树，从穿过山谷的小径上就能看见。','A lone oak stood on the hillock above the meadow / visible from the footpath / that crossed the valley.','hillock 指小山丘；above 表示其高于草地。','矮小隆起地形上长着一棵树，符合 s1。'),M('The survey marked the towering mountain range as a tiny hillock only a few centimeters high.','The survey marked the small mound as a hillock and the towering peaks as mountains.','高耸山脉不是小土丘。'),[Q('hillock',1,1,'A hillock is?','a small hill or mound','a very deep harbor','a large high-rise','hillock 指小山丘。'),Q('hillock',2,1,'An oak on a hillock stands on?','a small raised area of land','a flat underwater plain','a high-ranking desk','hillock 是小块隆起地形。'),Q('hillock',3,1,'Hillock is related to which word?','hill','hiss','hire','hillock 由 hill 派生。'),Q('hillock',4,1,'Which landform is smaller than a mountain?','a hillock','a skyscraper','a canyon floor','hillock 是小山丘。')]);
P('hillside','hillside 由 hill 与 side 组成，指从山脚到山顶之间的山坡侧面。',C('hillside.s1','土地利用','Rows of grapevines covered the sunny hillside, while stone walls divided the slope into narrow terraces.','一排排葡萄藤覆盖着向阳的山坡，石墙则把坡地分隔成狭窄梯田。','Rows of grapevines covered the sunny hillside / while stone walls divided the slope / into narrow terraces.','hillside 指山的侧坡；while 对比植被和石墙如何分布在坡面上。','葡萄藤生长在山坡侧面，符合 s1。'),M('The farmhouse stood on the hillside at the foot of a completely flat plain with no slope.','The farmhouse stood beside the flat plain, away from any hillside.','没有坡面的平原不能称为 hillside。'),[Q('hillside',1,1,'A hillside is?','the sloping side of a hill','the top floor of a high-rise','a flat sea route','hillside 指山坡。'),Q('hillside',2,1,'A hillside vineyard has vines growing?','on a slope of a hill','inside an airport terminal','under the ocean','葡萄园可以覆盖山坡。'),Q('hillside',3,1,'Hillside is formed from hill and?','side','school','rank','hillside 是 hill 与 side 的复合词。'),Q('hillside',4,1,'A road cut into a hillside runs along?','the side slope of a hill','a completely level ocean','the roof of a building','道路沿山坡侧面开凿。')]);
P('hilly','hilly 由 hill 加 -y 构成，形容地势有许多丘陵或像山丘般起伏倾斜的。',C('hilly.s1','骑行路线','The hilly route took longer than the map suggested because the cyclists had to climb several short but steep slopes.','这条丘陵路线比地图标示的耗时更久，因为骑行者必须爬过几段短而陡的坡。','The hilly route took longer than the map suggested / because the cyclists had to climb / several short but steep slopes.','hilly 修饰 route，表示沿途多坡；because 解释路线耗时的原因。','多段陡坡使路线起伏，符合 s1。'),M('The hilly landscape was perfectly level, with no raised ground or sloping roads anywhere.','The flat landscape was perfectly level, with no raised ground or sloping roads anywhere.','没有起伏坡地的景观应称平坦，不是 hilly。'),[Q('hilly',1,1,'A hilly region is?','covered with hills or slopes','entirely flat','mostly underwater','hilly 表示丘陵起伏的。'),Q('hilly',2,1,'A hilly cycling route often includes?','repeated climbs and descents','no changes in elevation','a set of indoor stairs only','多次爬坡下坡说明路线多丘陵。'),Q('hilly',3,1,'The suffix -y in hilly suggests?','having or characterized by hills','without hills','the person who hikes','-y 表示有……特征的。'),Q('hilly',4,1,'Which place is most likely hilly?','a landscape with rolling slopes','a level salt pan','a deep ocean trench','有滚动坡面的地形是 hilly。')]);
P('him','him 是 he 的宾格形式，可作动词或介词的宾语；较旧的非正式用法中也曾泛指任意性别的人。',C('him.s2','用语变迁','An older notice said, “If a visitor needs help, ask him at the desk”; the revised version uses “them” for an unspecified person.','一则旧告示写道：“如果访客需要帮助，请在服务台问他”；修订版本对性别未明的人使用 them。','An older notice said / “If a visitor needs help, ask him at the desk” / the revised version uses “them” / for an unspecified person.','这里展示较旧的泛指 him 用法，同时说明当代常用 them 指未指明性别的人。','引号中 him 作为泛指人的代词，符合 s2。'),M('The style guide says him is the only correct pronoun for every person, regardless of gender or context.','The style guide notes that him is masculine and recommends a suitable gender-neutral form when needed.','him 主要是阳性宾格代词，并非所有人的唯一正确代词。'),[Q('him',1,1,'In “I called him,” him is?','the object form of a male pronoun','a possessive adjective','a reflexive pronoun','him 是 he 的宾格。'),Q('him',2,2,'An older generic use of him could refer to?','a person of unspecified sex','only a building','a female subject in every case','词条还记录了旧式泛指用法。'),Q('him',3,1,'Which sentence uses him as an object?','The guide spoke to him.','Him book is on the table.','He blamed herself.','介词 to 后用宾格 him。'),Q('him',4,2,'For an unspecified person today, many writers prefer?','they or them where appropriate','him in every context','himself for everyone','当代常用 they/them 泛指性别未明者。')]);
P('himself','himself 可作反身代词指回男性主语，也可强调“他本人”，或表示恢复到平常身心状态。',C('himself.s3','康复叙述','After resting for a few days, Daniel said he felt himself again and returned to his normal work schedule.','休息几天后，丹尼尔说自己恢复了平常状态，并重新回到正常工作安排。','After resting for a few days / Daniel said he felt himself again / and returned / to his normal work schedule.','feel himself again 表示恢复平日的身心状态；again 强调状态回归。','他重新感到自己恢复如常，符合 s3。'),M('After the illness, Daniel said he felt himself again, meaning he had become completely unlike his usual self.','After the illness, Daniel said he still did not feel himself and had not returned to normal.','feel himself again 表示恢复常态，而非变得不像自己。'),[Q('himself',1,1,'In “He blamed himself,” himself refers to?','the same male person as the subject','another man','his possession','反身代词回指主语。'),Q('himself',2,2,'“The director himself welcomed us” emphasizes that?','the director personally welcomed us','someone else did it without him','the director was ill','himself 可用于强调本人亲自做。'),Q('himself',3,3,'If he feels himself again, he?','has returned to his usual state','is hiding from everyone','is blaming another person','feel himself again 表示恢复如常。'),Q('himself',4,1,'Which sentence uses himself reflexively?','He introduced himself to the group.','The coat is his.','They helped him.','introduced himself 中反身代词回指主语。')]);
P('hind','hind 源自古英语 hindan“在后面”，作形容词指位于后部的，尤其描述动物身体的后侧或后腿。',C('hind.s1','动物观察','The vet examined the dog’s hind legs after it began limping, then checked whether the paws were swollen.','狗开始跛行后，兽医检查了它的后腿，随后查看爪子是否肿胀。','The vet examined the dog’s hind legs / after it began limping / then checked / whether the paws were swollen.','hind 修饰 legs，表示身体后部的腿；after 引出检查原因。','兽医检查的是狗身体后部的腿，符合 s1。'),M('The rabbit’s hind legs were at the front of its body beside its head.','The rabbit’s front legs were beside its head, while its hind legs were at the back.','位于头部旁的是前腿，不是后腿。'),[Q('hind',1,1,'A hind leg is?','a leg at the back of an animal','a leg beside its head','a type of hillside','hind 表示后面的。'),Q('hind',2,1,'A horse’s hindquarters are located?','at the rear of its body','in front of its ears','under its front hooves','hind 表示后部。'),Q('hind',3,1,'Which phrase is natural?','hind legs','hind eyes','hind greeting','hind 常修饰身体后部结构。'),Q('hind',4,1,'The opposite of hind in this body-position sense is?','front','rear','back','front 与 hind 相对。')]);
P('hinder','hinder 源自古英语 hindrian，指使某人的进展更困难，或阻止、延误某事按时发生。',C('hinder.s2','项目执行','A late permit could hinder the bridge opening from taking place on schedule, so the contractor submitted the documents early.','许可证延迟可能妨碍桥梁按计划开放，因此承包商提前提交了文件。','A late permit could hinder the bridge opening / from taking place on schedule / so the contractor submitted the documents early.','hinder ... from taking place 表示阻止某事发生；could 表示潜在影响。','许可证延误可能使开放时间推迟，符合 s2。'),M('The missing permit hindered the launch by ensuring that it took place exactly on time with no delay.','The missing permit delayed the launch and prevented it from taking place on time.','让活动准时完成与 hinder 导致延误的意义相反。'),[Q('hinder',1,1,'To hinder someone’s progress is to?','make it more difficult for them to advance','help them move forward','praise them publicly','hinder 表示妨碍进展。'),Q('hinder',2,2,'A missing permit may hinder an opening by?','preventing it from happening on time','making it happen earlier','decorating the entrance','hinder 可指阻止或延误按时发生。'),Q('hinder',3,1,'Which phrase is natural?','hinder progress','hinder a high-ranking','hinder a history','hinder 常接 progress 或行动。'),Q('hinder',4,2,'The closest meaning of hinder is?','obstruct or delay','encourage','celebrate','obstruct、delay 与 hinder 接近。')]);
P('hindquarters','hindquarters 由 hind 与 quarters 组成，指四足动物身体后部，包括后腿、臀部和髋部。',C('hindquarters.s1','兽医检查','The veterinarian examined the horse’s hindquarters for swelling after it slipped during training.','马在训练中滑倒后，兽医检查了它的后躯是否肿胀。','The veterinarian examined the horse’s hindquarters / for swelling / after it slipped / during training.','hindquarters 指四足动物的后躯；for swelling 说明检查内容。','检查部位包括马身体后部及后腿，符合 s1。'),M('The vet called the horse’s head and front legs its hindquarters.','The vet called the horse’s rear body and hind legs its hindquarters.','头部和前腿在身体前方，不属于 hindquarters。'),[Q('hindquarters',1,1,'An animal’s hindquarters are?','its rear section, including hind legs and hips','its head and front legs','its stomach only','hindquarters 指动物后躯。'),Q('hindquarters',2,1,'A vet examining hindquarters is examining?','the rear part of a four-legged animal','the animal’s ears','its habitat','hindquarters 包括后腿与髋臀部。'),Q('hindquarters',3,1,'The word hindquarters is most often used for?','the rear body of an animal','a high-rise building','a person’s history','该词常指动物后躯。'),Q('hindquarters',4,1,'Hind in hindquarters means?','at the back','at the front','in the middle','hind 表示后面的。')]);
P('hindrance','hindrance 由 hinder 加名词后缀 -ance 构成，指妨碍进展、使行动更困难的事物或障碍。',C('hindrance.s1','无障碍出行','The broken elevator was a serious hindrance for residents who used wheelchairs, so the building manager arranged temporary ground-floor access.','电梯损坏给使用轮椅的居民造成了严重障碍，因此楼宇经理安排了临时的一层出入口。','The broken elevator was a serious hindrance / for residents who used wheelchairs / so the building manager arranged / temporary ground-floor access.','hindrance 指阻碍或困难；so 引出应对障碍的安排。','故障妨碍居民进入住所，符合 s1。'),M('The missing elevator was a hindrance because it made every floor easier and faster for wheelchair users to reach.','The missing elevator was a hindrance because it made upper floors difficult for wheelchair users to reach.','使行动更困难的是 hindrance，不是让楼层更容易到达。'),[Q('hindrance',1,1,'A hindrance is?','something that blocks or slows progress','a helpful shortcut','a kind of high-ranking job','hindrance 指障碍。'),Q('hindrance',2,1,'A broken elevator can be a hindrance because it?','makes access to upper floors difficult','makes every floor easier to reach','turns a building into a hillside','阻碍行动的故障是 hindrance。'),Q('hindrance',3,1,'Which phrase is natural?','a hindrance to progress','a hindrance of high-school','a hindrance of herring','hindrance to progress 是常见搭配。'),Q('hindrance',4,1,'The closest meaning of hindrance is?','obstacle','advantage','highlight','obstacle 与 hindrance 接近。')]);
P('hindsight','hindsight 由 hind“在后”与 sight 组成，指事情发生后回头看时才获得的理解或判断。',C('hindsight.s1','项目复盘','With hindsight, the team realized that testing the backup system earlier would have prevented the long service outage.','事后回看，团队意识到如果更早测试备用系统，就能避免长时间服务中断。','With hindsight / the team realized / that testing the backup system earlier / would have prevented the long service outage.','with hindsight 表示事后回顾；would have prevented 描述对过去的反事实判断。','只有故障发生后，团队才明白早测备份的重要性，符合 s1。'),M('With hindsight, the team knew exactly what would happen before the event occurred.','Beforehand, the team predicted exactly what would happen before the event occurred.','hindsight 是事后才获得的认识，不能表示事件前的预知。'),[Q('hindsight',1,1,'Hindsight is?','understanding gained after an event happens','knowledge of the future before it occurs','a type of highway','hindsight 指事后之明。'),Q('hindsight',2,1,'“With hindsight” means?','looking back after the result is known','guessing before anything happens','looking through a telescope','with hindsight 表示事后回看。'),Q('hindsight',3,1,'Someone may say “In hindsight, I should have called” because?','they see the better choice only after the event','they had perfect knowledge of the future','they are describing a physical obstacle','事后才看出更好选择体现 hindsight。'),Q('hindsight',4,1,'Hindsight differs from foresight because it looks?','backward at what has already happened','ahead to what may happen','only at the present weather','hindsight 回看过去，foresight 预见未来。')]);
P('hinge','hinge 源自古诺尔斯语 hengja“悬挂”，可作名词指使门或盖子转动的铰链，也可作动词表示安装铰链。',C('hinge.s1','家具维修','The cabinet door sagged because one hinge had loosened, so the carpenter tightened its screws before replacing the panel.','柜门因一个铰链松动而下垂，因此木匠在更换面板前拧紧了螺丝。','The cabinet door sagged / because one hinge had loosened / so the carpenter tightened its screws / before replacing the panel.','hinge 指连接门与柜体、使其转动的合页；because 引出下垂原因。','螺丝松动的转动连接件是铰链，符合 s1。'),M('The cabinet hinge was a fixed solid block that prevented the door from swinging at all.','The cabinet latch held the door closed, while its hinge allowed it to swing.','hinge 的作用是让门转动，而不是完全阻止转动。'),[Q('hinge',1,1,'A door hinge is?','a joint that allows a door to swing','a lock that never moves','a kind of fish','hinge 指门铰链。'),Q('hinge',2,2,'A plan may hinge on one fact, meaning it?','depends on that fact','is attached to a door','has already been canceled','hinge on 可比喻取决于。'),Q('hinge',3,3,'To hinge a lid is to?','attach it with a joint that lets it swing','paint it a different color','hide it in a drawer','动词 hinge 可指给盖子装铰链。'),Q('hinge',4,1,'Which object commonly has a hinge?','a cabinet door','a sheet of paper with no fold','a herring','门通常通过铰链转动。')]);
P('hinge on','hinge on 是固定短语，表示某项结果或决定完全取决于某个条件、事实或关键因素。',C('hinge on.s1','项目决策','Whether the outdoor concert can proceed will hinge on the weather forecast issued on the morning of the event.','户外音乐会能否举行，将取决于活动当天早晨发布的天气预报。','Whether the outdoor concert can proceed / will hinge on the weather forecast / issued on the morning / of the event.','hinge on + 条件表示取决于；whether 从句说明待决定的结果。','音乐会能否举行由天气预报决定，符合 s1。'),M('The concert hinged on the forecast, but the organizers made the decision without considering the forecast at all.','The concert depended on the forecast, so the organizers checked it before deciding.','若完全不考虑预报，决定就不是取决于预报。'),[Q('hinge on',1,1,'If a result hinges on a condition, it?','depends on that condition','is attached to a physical door','has nothing to do with it','hinge on 表示取决于。'),Q('hinge on',2,1,'“The launch hinges on approval” means?','approval will determine whether the launch happens','the launch is a type of door','approval came after the launch','结果取决于批准。'),Q('hinge on',3,1,'Which phrase is natural?','success hinges on careful timing','success hinges from careful timing','success hinges at careful timing','常用结构是 hinge on。'),Q('hinge on',4,1,'A decision that hinges on evidence?','depends on the evidence','is independent of all evidence','is physically attached to a file','比喻用法表示依赖证据。')]);
P('hint','hint 的确切词源尚不确定；现代可作名词指间接暗示、帮助性线索或微量，也可作动词表示含蓄暗示。',C('hint.s4','工作沟通','The manager hinted that the deadline might change, but she waited for the official notice before confirming a new date.','经理暗示截止日期可能会变，但她等到正式通知后才确认新日期。','The manager hinted that the deadline might change / but she waited for the official notice / before confirming a new date.','hint that + 从句表示含蓄透露信息；but 表明暗示不等同于正式确认。','经理间接表达日期可能变化，符合 s4。'),M('The manager hinted the exact new deadline by publishing a clear official notice with the confirmed date.','The manager announced the exact new deadline in a clear official notice.','明确正式公布日期是直接宣布，不是含蓄暗示。'),[Q('hint',1,1,'A hint can be?','an indirect suggestion','a complete formal contract','a high-rise building','hint 可指暗示。'),Q('hint',2,2,'A hint in a puzzle is?','a small piece of helpful information','the final answer itself every time','a kind of fish','hint 也指提示或线索。'),Q('hint',3,3,'A hint of lemon in a drink means?','a very small amount or trace of lemon flavor','a whole lemon fruit','no flavor at all','hint 可表示微量。'),Q('hint',4,4,'To hint that plans may change is to?','suggest it indirectly','announce a confirmed change formally','hide every fact without a word','hint 作动词表示含蓄暗示。')]);
P('hinterland','hinterland 源自德语 hinter“后方”与 Land“土地”，指远离海岸或主要城市的内陆地区。',C('hinterland.s1','区域交通','The port’s hinterland includes inland towns that depend on the rail line to move grain and manufactured goods to the coast.','港口的腹地包括依靠铁路将粮食和制成品运往海岸的内陆城镇。','The port’s hinterland includes inland towns / that depend on the rail line / to move grain and manufactured goods / to the coast.','hinterland 指港口或沿海地区后方的内陆；that 从句说明城镇与港口的联系。','这些城镇位于沿海港口背后的内陆，符合 s1。'),M('The port’s hinterland consisted only of ships floating offshore, with no inland areas or towns.','The port’s hinterland consisted of inland towns connected to the coast by rail.','hinterland 指内陆腹地，不是海上的船只。'),[Q('hinterland',1,1,'A port’s hinterland is?','the inland region connected to and served by the port','the open sea beyond the harbor','the port’s ticket office','hinterland 指港口腹地。'),Q('hinterland',2,1,'Hinterland comes from German elements meaning?','land behind or inland','six-sided stone','high-ranking office','hinterland 源自“后方土地”一类含义。'),Q('hinterland',3,1,'A town far inland from the coast may lie in a?','hinterland','hallway','high-rise','远离海岸的内陆可称 hinterland。'),Q('hinterland',4,1,'The opposite of coastal in this context is?','inland','historic','hilarious','hinterland 是内陆地区。')]);
P('hip','hip 有多个词源不同的义项：身体髋部来自古英语 hype，蔷薇果另有来源；口语 hip 还可表示时髦、赶时髦的。',C('hip.s4','音乐文化','The small record shop became hip with local students after it began hosting live sets by new neighborhood artists.','这家小唱片店开始举办本地新锐艺人的现场演出后，在学生中变得很时髦。','The small record shop became hip with local students / after it began hosting live sets / by new neighborhood artists.','hip 作口语形容词表示时髦、受欢迎；became 表示状态变化。','店铺因新音乐活动受到年轻人欢迎，符合 s4。'),M('The shop was considered hip because it was unfashionable, ignored by everyone, and closed for years.','The shop was considered outdated because it was unfashionable and ignored by everyone.','过时且无人问津与 hip 表示的时髦受欢迎相反。'),[Q('hip',1,1,'A person’s hip is?','the joint area above the leg on either side','the back of the head','a type of highway','hip 可指臀部与髋部。'),Q('hip',2,2,'The hips of a garment are?','the part covering the body’s hip area','the sleeves','the collar only','hip 也指衣服覆盖臀部的部位。'),Q('hip',3,3,'A rose hip is?','the red fruit of a wild rose','a hip joint','a kind of herring','hip 还可指蔷薇果。'),Q('hip',4,4,'In informal speech, a hip café is?','fashionable and trendy','painful to walk into','a historical archive','hip 可口语表示时髦的。')]);
P('hip-hop','hip-hop 是 hip 与 hop 组成的文化与音乐名称，指源自街头文化、以节奏和韵律为特色的音乐形式。',C('hip-hop.s1','音乐课程','The class traced hip-hop’s development through recorded beats, spoken-word performance, dance, and local community events.','课程通过录制节拍、口语表演、舞蹈和本地社区活动，追溯了嘻哈的发展。','The class traced hip-hop’s development / through recorded beats, spoken-word performance, dance, / and local community events.','hip-hop 指音乐及相关文化；through 后列出研究其发展的材料和表现形式。','节拍、韵律表演和舞蹈体现嘻哈文化。'),M('The guide described hip-hop as a silent form of classical music with no rhythm, words, or dance.','The guide described hip-hop as a music culture with rhythm, spoken performance, and dance.','完全无节奏、语言和舞蹈的描述与 hip-hop 的常见特征相反。'),[Q('hip-hop',1,1,'Hip-hop is associated with?','street music and culture built around rhythm','a medical specialist','a six-sided polygon','hip-hop 指嘻哈音乐文化。'),Q('hip-hop',2,1,'A hip-hop performance may include?','rhythmic music and spoken-word delivery','only silent reading','a high-ranking speech','节奏音乐与韵律表达常见于嘻哈。'),Q('hip-hop',3,1,'Which phrase is natural?','hip-hop music','hip-hop herring','hip-hop hindquarters','hip-hop 可修饰 music。'),Q('hip-hop',4,1,'Hip-hop is best treated as?','a musical and cultural genre','a type of mineral','a hallway design','它是一种音乐文化类型。')]);
P('hippopotamus','hippopotamus 源自希腊语 hippopotamos“河马”，由 hippos“马”与 potamos“河”构成，指大型半水生草食哺乳动物。',C('hippopotamus.s1','动物园观察','The hippopotamus rested in the pool during the hot afternoon, surfacing regularly while keepers monitored its enclosure.','炎热的午后，河马在水池里休息，定时浮出水面，饲养员则监测其活动场地。','The hippopotamus rested in the pool during the hot afternoon / surfacing regularly / while keepers monitored its enclosure.','hippopotamus 指河马；surfacing regularly 描述它在水中休息时浮出水面的情景。','大型草食动物长时间在水中活动，符合 s1。'),M('The hippopotamus was described as a tiny fish that lived only in dry mountain air.','The hippopotamus was described as a large mammal that spends much of its time in water.','河马是大型哺乳动物，不是生活在干燥高山空气中的小鱼。'),[Q('hippopotamus',1,1,'A hippopotamus is?','a large mostly hairless mammal that spends much time in water','a tiny fish from the North Atlantic','a six-sided insect','hippopotamus 指河马。'),Q('hippopotamus',2,1,'The Greek roots of hippopotamus roughly mean?','river horse','high hill','hidden animal','hippos 与 potamos 合起来表示“河马”。'),Q('hippopotamus',3,1,'A hippopotamus is mainly?','a plant-eating mammal','a carnivorous bird','a type of herring','河马主要以植物为食。'),Q('hippopotamus',4,1,'Where does a hippopotamus often spend much of the day?','in water','in a high-rise','in a dry cave','河马白天常待在水中。')]);
P('hire','hire 源自古英语 hyrian，可指短期雇用人员、付费租用物品，也可作名词指租金或雇用行为。',C('hire.s2','出行租赁','We decided to hire a car for the final day because the small villages were not served by the bus network.','我们决定最后一天租一辆车，因为公交网络不到那些小村庄。','We decided to hire a car for the final day / because the small villages / were not served / by the bus network.','hire a car 表示付费短期租车；because 引出租车的原因。','支付费用临时使用汽车，符合 s2。'),M('They hired a car by purchasing it permanently and transferring the vehicle title into their names.','They bought a car permanently and transferred the vehicle title into their names.','永久购买并取得所有权不是短期租用。'),[Q('hire',1,1,'To hire a worker is to?','employ them for a job or period','sell them a vehicle','borrow their history book','hire 可指雇用。'),Q('hire',2,2,'To hire a car is to?','pay to use it temporarily','purchase it permanently','repair its hinge','hire 可指短期租用。'),Q('hire',3,3,'The hire of equipment may refer to?','the money paid to rent it','the item’s weight','a job applicant only','hire 可作名词指租金。'),Q('hire',4,4,'The hire of new staff means?','the act of employing them','the act of dismissing them','a price increase','hire 可指雇佣行为。')]);
P('hire charge','hire charge 是 hire 与 charge 组成的名词短语，指租用设备、车辆等物品所支付的费用。',C('hire charge.s1','设备租赁','The invoice listed a separate hire charge for the floor polisher, along with a refundable deposit and delivery fee.','发票把地板抛光机的租赁费单独列出，此外还有可退还押金和配送费。','The invoice listed a separate hire charge for the floor polisher / along with a refundable deposit / and delivery fee.','hire charge 指租用物品的费用；along with 表示费用项目并列。','发票单列短期使用设备的费用，符合 s1。'),M('The invoice called the hire charge a refund paid to the customer for returning equipment unused.','The invoice called the hire charge the fee paid to use the equipment temporarily.','租赁费是使用物品需支付的费用，不是退还给顾客的钱。'),[Q('hire charge',1,1,'A hire charge is?','money paid to rent something temporarily','a salary paid to a permanent employee','a vehicle’s top speed','hire charge 指租赁费。'),Q('hire charge',2,1,'A company might add a hire charge for?','renting a floor polisher','buying a book permanently','borrowing a free hint','租用设备会产生 hire charge。'),Q('hire charge',3,1,'Which phrase is natural?','a daily hire charge','a hirsute hire charge','a historical hire charge of a river','hire charge 常说明租用费用。'),Q('hire charge',4,1,'A hire charge differs from a refundable deposit because it is?','the rental fee for temporary use','always returned in full','the item being rented','租赁费是使用的价款，不是押金。')]);
P('hirsute','hirsute 源自拉丁语 hirsutus“多粗毛的”，形容身上或表面长有很多粗硬、蓬乱毛发的。',C('hirsute.s1','动物观察','The hirsute terrier needed regular brushing because its coarse coat collected burrs after walks through the field.','这只毛发粗密的梗犬需要定期梳理，因为它在田野散步后，粗糙的被毛上会粘满刺果。','The hirsute terrier needed regular brushing / because its coarse coat collected burrs / after walks through the field.','hirsute 修饰 terrier，表示毛发浓密粗硬；because 引出需要梳理的原因。','粗密被毛容易粘上刺果，符合 s1。'),M('The hirsute animal had smooth bare skin with no hair anywhere on its body.','The hairless animal had smooth bare skin with no hair anywhere on its body.','全身无毛与 hirsute 的多粗毛含义相反。'),[Q('hirsute',1,1,'A hirsute animal has?','a lot of coarse or shaggy hair','no hair at all','a six-sided body','hirsute 表示多粗毛的。'),Q('hirsute',2,1,'Which animal might be described as hirsute?','one with a thick, shaggy coat','a hairless animal with smooth skin','a fish with no fur','粗密蓬乱的被毛符合 hirsute。'),Q('hirsute',3,1,'Hirsute comes from a Latin word meaning?','hairy or shaggy','historical','high-ranking','其拉丁词源表示多毛。'),Q('hirsute',4,1,'The closest opposite of hirsute is?','hairless','shaggy','hilly','hairless 与多毛相反。')]);
P('his','his 是 he 的所有格形式，可作限定词修饰名词，也可作名词性物主代词独立表示属于他的东西。',C('his.s2','物品归属','The red bicycle is hers, and the blue one is his; both owners left their helmets beside the door.','红色自行车是她的，蓝色的是他的；两位车主都把头盔留在门边。','The red bicycle is hers / and the blue one is his / both owners left their helmets / beside the door.','his 在此独立作名词性物主代词，代替 his bicycle；分号连接相关说明。','his 指属于男性车主的那辆蓝色自行车，符合 s2。'),M('The blue bicycle is his helmet, so he rode the bicycle home.','The blue bicycle is his, and his helmet is beside the door.','his 作名词性物主代词时不直接接 helmet；限定词形式 his helmet 意为“他的头盔”。'),[Q('his',1,1,'In “His coat is wet,” his is?','a possessive word before a noun','the object form of he','a reflexive pronoun','his 可作名词前的限定词。'),Q('his',2,2,'In “The coat is his,” his means?','the coat belongs to him','he is wearing someone else’s coat','the coat belongs to her','独立 his 表示属于他的东西。'),Q('his',3,1,'Choose the correct phrase for a male person’s book.','his book','him book','himself book','名词前使用限定词 his。'),Q('his',4,2,'Which form can stand alone at the end of a sentence?','The blue bag is his.','The blue bag is he.','The blue bag is hims.','his 可独立作名词性物主代词。')]);
P('Hispanic','Hispanic 源自拉丁语 Hispanicus，形容与西班牙或美洲西班牙语国家及其人民有关；具体身份用语应尊重个人偏好。',C('Hispanic.s1','博物馆编目','The museum grouped works by Hispanic artists from several Spanish-speaking countries in the Americas and listed each artist’s country and background.','博物馆将来自美洲多个西班牙语国家的西班牙裔艺术家的作品编在一起，并注明每位艺术家的国家和背景。','The museum grouped works by Hispanic artists / from several Spanish-speaking countries in the Americas / and listed each artist’s country / and background.','Hispanic 在此作形容词描述与西班牙语美洲群体相关的艺术家；逐人注明背景避免把多元群体混为一谈。','艺术家来自多个西班牙语国家，符合 s1 且保留个体差异。'),M('The catalog treated every Hispanic community as one identical culture and refused to identify any country or individual background.','The catalog noted that Hispanic communities are diverse and identified each artist’s own country and background.','把不同国家和个人背景一概视作相同，会抹去群体内部的多样性。'),[Q('Hispanic',1,1,'Hispanic can describe something connected with?','Spain or Spanish-speaking countries and peoples in the Americas','every country in Asia','only one identical cultural tradition','Hispanic 的词义涉及西班牙及美洲西班牙语地区。'),Q('Hispanic',2,1,'A careful description of Hispanic artists should?','recognize the different countries and backgrounds represented','assume all artists share exactly one experience','avoid naming any individual','准确表述应保留不同国家和背景。'),Q('Hispanic',3,1,'Hispanic is related to the Latin word for?','Spain','six','river','Hispanicus 与西班牙相关。'),Q('Hispanic',4,1,'Which phrase is natural?','Hispanic communities in the Americas','Hispanic herring','Hispanic high-rise angle','该词可修饰相关群体或文化。')]);
P('hiss','hiss 可作动词表示发出尖锐的嘶声或嘘声，也可作名词指这种类似字母 s 的声音。',C('hiss.s1','设备检修','Steam hissed from the loose pipe joint, so the technician shut down the boiler and checked the connection.','蒸汽从松动的管道接头处嘶嘶泄出，因此技术员关闭锅炉并检查连接处。','Steam hissed from the loose pipe joint / so the technician shut down the boiler / and checked the connection.','hiss 描述蒸汽发出的尖锐持续声；so 引出安全处置。','蒸汽从接头处发出嘶声，符合动词义。'),M('The pipe hissed by remaining completely silent while no steam or air escaped.','The pipe remained silent while no steam or air escaped.','没有任何声音或气体泄漏时不能说管道发出嘶声。'),[Q('hiss',1,1,'To hiss is to?','make a sharp s-like sound','make no sound at all','walk up a hill','hiss 可指发嘶嘶声。'),Q('hiss',2,2,'A hiss from a crowd may express?','disapproval','a warm greeting','a medical history','观众嘘声可表示不满。'),Q('hiss',3,1,'Which source may hiss?','steam escaping from a pipe','a silent stone','a printed history book','蒸汽泄漏可能发出嘶声。'),Q('hiss',4,2,'A hiss can also be?','the sharp s-like noise itself','a person who hikes','a high-end price','hiss 也可作名词指嘶声。')]);
P('historian','historian 由 history 加表示从业者的 -ian 构成，指研究历史或撰写历史的人，也可指记录某一时代事件的作者。',C('historian.s1','档案研究','The historian compared letters, tax records, and maps before writing an account of how the port changed over two centuries.','这位历史学家在撰写港口两个世纪以来的变化之前，比较了信件、税务记录和地图。','The historian compared letters, tax records, and maps / before writing an account / of how the port changed / over two centuries.','historian 指研究或撰写历史的人；before 引出写作前的史料核查。','作者利用多种史料研究过去，符合 s1。'),M('The historian wrote about two centuries of port history without studying records, events, or any evidence from the past.','The novelist wrote an imagined story without relying on historical records.','不研究过去事件或史料的人不符合 historian 的研究者义。'),[Q('historian',1,1,'A historian is someone who?','studies or writes about the past','repairs hinges','raises highway fees','historian 指历史学家。'),Q('historian',2,2,'A historian who records events as they happen may be?','a writer documenting the events of a time','a hiker on a trail','a high-ranking official only','historian 也可指时代事件记录者。'),Q('historian',3,1,'A historian may consult?','letters, archives, and other historical evidence','only a weather forecast','a list of hairdos','史学研究常使用档案与历史证据。'),Q('historian',4,2,'The suffix -ian in historian refers to?','a person associated with a field','a six-sided shape','a past-tense action','-ian 可表示从事或研究某领域的人。')]);
P('historic','historic 由 history 加 -ic 构成，形容对历史有重大意义、会被载入史册的事件或时刻。',C('historic.s1','公共事件','The signing of the peace accord was a historic moment that ended decades of conflict between the two countries.','和平协议的签署是一个具有历史意义的时刻，结束了两国数十年的冲突。','The signing of the peace accord was a historic moment / that ended decades of conflict / between the two countries.','historic 修饰 moment，强调该时刻因重大影响而载入历史；that 从句说明意义。','结束长期冲突的时刻具有重要历史意义，符合 s1。'),M('The newspaper called the routine daily staff meeting a historic event, although it changed nothing and was never remembered.','The newspaper called the treaty signing a historic event because it changed relations between the countries.','普通且无重大影响、无人记得的日常会议不宜称为 historic。'),[Q('historic',1,1,'A historic event is?','important or famous in history','merely belonging to any past period','a person who studies history','historic 强调历史意义重大。'),Q('historic',2,1,'A historic agreement may?','change relations or shape later events','be an ordinary event with no lasting impact','refer only to a historical costume','重大协议可能影响后续历史。'),Q('historic',3,1,'Which phrase is natural?','a historic decision','a historic old coin only because it is old','a historic hallway rug','historic 常修饰重大决定或时刻。'),Q('historic',4,1,'Historic is closest to?','historically significant','merely old','hilarious','historic 表示有历史意义。')]);
P('historical','historical 由 history 加 -ical 构成，可指属于过去或基于真实过去事件的，也可指与历史研究、写作有关的。',C('historical.s1','史实核查','The museum corrected a historical date after researchers found a contemporary letter that recorded the ceremony more precisely.','研究人员找到一封更准确记录仪式日期的同时代信件后，博物馆修正了一个历史日期。','The museum corrected a historical date / after researchers found / a contemporary letter / that recorded the ceremony more precisely.','historical 修饰 date，表示与过去史实有关；after 从句说明修正依据。','日期属于过去事件，且根据当时信件核实，符合 s1。'),M('The curator called the invented future ceremony a historical event that had already happened centuries ago.','The curator called the ceremony a fictional future event rather than a historical event.','未来虚构的仪式不是已经发生的历史事件。'),[Q('historical',1,1,'A historical document is?','connected with the past or real past events','guaranteed to change the future','a person who writes fiction only','historical 可指历史上的、史实的。'),Q('historical',2,2,'Historical research is concerned with?','studying or writing about history','raising a price sharply','cutting hair','historical 也可表示史学研究的。'),Q('historical',3,1,'Which phrase is natural?','historical evidence from the archive','historic evidence that means only “old” in every case','hirsute evidence','historical 常修饰证据、事件或研究。'),Q('historical',4,2,'A historical novel is generally set in?','a past period','a future that has not happened','a gymnasium at present only','historical novel 通常以过去为背景。')]);
P('historically','historically 由 historical 加 -ly 构成，表示从历史角度来看、依据过去的长期事实或模式。',C('historically.s1','城市发展','Historically, the river served as the main route for trade, but modern freight now travels mostly by rail.','从历史上看，这条河曾是主要贸易通道，但如今货运大多改走铁路。','Historically / the river served as the main route for trade / but modern freight / now travels mostly by rail.','historically 修饰整句，表示依据过去的情况；but 对比现代变化。','句子回顾河流过去的作用，再与现状比较，符合 s1。'),M('Historically, the bridge will open next year, although no event from the past supports that future prediction.','According to the current schedule, the bridge will open next year.','historically 指过去的事实和模式，不能直接表示未来计划。'),[Q('historically',1,1,'Historically means?','when considering the past as evidence or a pattern','only in the future','in a hirsute manner','historically 表示从历史上看。'),Q('historically',2,1,'A historically important route?','has played an important role over time','will be built next year only','has no connection to the past','历史上重要意味着过去长期发挥作用。'),Q('historically',3,1,'Which sentence uses historically correctly?','Historically, the port connected inland towns to overseas trade.','Historically, tomorrow’s weather will be sunny.','Historically, the six-sided box has no past.','该词常用于概述过去模式。'),Q('historically',4,1,'Historically is the adverb related to?','historical','history book’s plural','hiss','historically 与 historical 同源。')]);
P('history','history 经古法语源自拉丁语 historia、希腊语 historia“探究、记述”，可指过去事件、历史学、个人或地方来历，也可指病史记录。',C('history.s4','医疗登记','Before prescribing treatment, the clinician reviewed the patient’s medical history, including allergies and previous reactions to medication.','开具治疗方案前，临床人员查看了患者的病史，包括过敏情况和以往对药物的反应。','Before prescribing treatment / the clinician reviewed the patient’s medical history / including allergies / and previous reactions to medication.','medical history 指患者既往疾病与健康记录；including 后列举记录内容。','既往过敏和药物反应属于病历资料，符合 s4。'),M('The intake form asked for medical history but told patients to leave every past illness and allergy unrecorded.','The intake form asked patients to record their past illnesses and allergies in their medical history.','要求提供病史却不记录任何疾病或过敏信息，前后矛盾。'),[Q('history',1,1,'History can mean?','events of the past or the study of them','a sudden greeting','a kind of mineral','history 可指历史事件或历史学。'),Q('history',2,2,'A history class studies?','the past and its events','only future plans','how to hire a car','history 可指学校里的历史学科。'),Q('history',3,3,'A town’s history may include?','its past record and background','only its current population','the color of its road signs','history 也指地方来历。'),Q('history',4,4,'A patient’s medical history is?','a record of past illnesses and health information','a list of every movie they watched','a future treatment guarantee','medical history 指病史记录。')]);

})();
